class UserMainCode(object):
    @classmethod
    def findSumOfPrimes(cls, input1, input2):

        def is_prime(n):
            if n < 2: return False
            for i in range(2, int(n**0.5)+1):
                if n % i == 0: return False
            return True

        primes = [x for x in input1 if is_prime(x)]

        if not primes:  
            return sum(input1) - min(input1)

        primes.remove(min(primes))
        return sum(primes)
