def split_questions(text):
    """
    Split multiple questions entered by the user.

    Supports:
    1. Question one?
    2. Question two?

    Also supports separate lines.
    """

    if not text:
        return []

    text = text.replace("\r\n", "\n").strip()

    if not text:
        return []

    questions = []

    # -----------------------------------------------------
    # First split by question mark
    # -----------------------------------------------------

    parts = re.split(r"\?", text)

    for part in parts:

        part = part.strip()

        if not part:
            continue

        part = re.sub(
            r"^\s*\d+\s*[\.\)\-:]\s*",
            "",
            part
        ).strip()

        if part:
            questions.append(part + "?")

    # -----------------------------------------------------
    # Handle multiline questions without ?
    # -----------------------------------------------------

    if len(questions) <= 1:

        lines = [
            line.strip()
            for line in text.split("\n")
            if line.strip()
        ]

        if len(lines) > 1:

            questions = []

            for line in lines:

                line = re.sub(
                    r"^\s*\d+\s*[\.\)\-:]\s*",
                    "",
                    line
                ).strip()

                if not line:
                    continue

                if not line.endswith("?"):
                    line += "?"

                questions.append(line)

    return questions


def get_numeric_columns(df):

    return (
        df
        .select_dtypes(include=np.number)
        .columns
        .tolist()
    )


def get_categorical_columns(df):

    return (
        df
        .select_dtypes(
            include=["object", "category", "bool"]
        )
        .columns
        .tolist()
    )


def get_date_columns(df):

    date_columns = []

    for column in df.columns:

        if pd.api.types.is_datetime64_any_dtype(
            df[column]
        ):

            date_columns.append(column)

        elif df[column].dtype == "object":

            converted = pd.to_datetime(
                df[column],
                errors="coerce"
            )

            if (
                converted.notna().mean() >= 0.70
                and converted.notna().sum() > 0
            ):

                date_columns.append(column)

    return date_columns


def safe_numeric_series(df, column):

    if column not in df.columns:
        return pd.Series(dtype=float)

    return (
        pd.to_numeric(
            df[column],
            errors="coerce"
        )
        .replace(
            [np.inf, -np.inf],
            np.nan
        )
        .dropna()
    )


def find_column(df, candidates):

    normalized = {
        str(column).strip().lower().replace(" ", "_"): column
        for column in df.columns
    }

    # -----------------------------------------------------
    # Exact matching
    # -----------------------------------------------------

    for candidate in candidates:

        key = (
            candidate
            .strip()
            .lower()
            .replace(" ", "_")
        )

        if key in normalized:
            return normalized[key]

    # -----------------------------------------------------
    # Partial matching
    # -----------------------------------------------------

    for column in df.columns:

        column_key = (
            str(column)
            .lower()
            .replace(" ", "_")
        )

        for candidate in candidates:

            candidate_key = (
                candidate
                .lower()
                .replace(" ", "_")
            )

            if candidate_key in column_key:
                return column

    return None


def detect_sales_column(df):

    return find_column(
