def format_number(value):

    if value is None:
        return "N/A"

    try:

        value = float(value)

        if math.isnan(value):
            return "N/A"

        if value.is_integer():
            return f"{int(value):,}"

        return f"{value:,.2f}"

    except Exception:

        return str(value)


def clean_dataframe(df):

    cleaned = df.copy()

    # Remove completely empty rows
    cleaned = cleaned.dropna(
        how="all"
    )

    # Remove completely empty columns
    cleaned = cleaned.dropna(
        axis=1,
        how="all"
    )

    # Clean column names
    cleaned.columns = [
        str(column).strip()
        for column in cleaned.columns
    ]

    # Remove duplicate column names safely
    seen = {}

    new_columns = []

    for column in cleaned.columns:

        if column not in seen:

            seen[column] = 0
            new_columns.append(column)

        else:

            seen[column] += 1

            new_columns.append(
                f"{column}_{seen[column]}"
            )

    cleaned.columns = new_columns

    return cleaned


def call_ollama(prompt, timeout=120):

    try:

        response = requests.post(
            "http://localhost:11434/api/generate",
            json={
                "model": "llama3",
                "prompt": prompt,
                "stream": False,
                "options": {
                    "temperature": 0.1
                }
            },
            timeout=timeout
        )

        if response.status_code != 200:

            return None, (
                f"Ollama returned HTTP "
                f"{response.status_code}: "
                f"{response.text}"
            )

        data = response.json()

        answer = (
            data
            .get("response", "")
            .strip()
        )

        if not answer:

            return None, (
                "Ollama returned an empty response."
            )

        return answer, None

    except requests.exceptions.ConnectionError:

        return None, (
            "Ollama is not running. "
            "Start Ollama and make sure the llama3 model is available."
        )

    except requests.exceptions.Timeout:

        return None, (
            "Ollama took too long to respond."
        )

    except Exception as e:

        return None, str(e)


