def detect_question_type(question):

    q = question.lower().strip()

    # Highest must be checked before general comparison
    if any(
        phrase in q
        for phrase in [
            "top ",
            "highest",
            "maximum",
            "most",
            "best"
        ]
    ):
        return "highest"

    if any(
        phrase in q
        for phrase in [
            "lowest",
            "minimum",
            "least",
            "bottom"
        ]
    ):
        return "lowest"

    if any(
        phrase in q
        for phrase in [
            "average",
            "mean",
            "avg"
        ]
    ):
        return "average"

    if any(
        phrase in q
        for phrase in [
            "compare",
            "comparison",
            "versus",
            " vs ",
            "difference"
        ]
    ):
        return "comparison"

    if any(
        phrase in q
        for phrase in [
            "trend",
            "over time",
            "monthly",
            "daily",
            "weekly",
            "yearly"
        ]
    ):
        return "trend"

    if any(
        phrase in q
        for phrase in [
            "distribution",
            "spread"
        ]
    ):
        return "distribution"

    if any(
        phrase in q
        for phrase in [
            "correlation",
            "relationship",
            "related"
        ]
    ):
        return "correlation"

    return "general"


