def create_question_visualization(df, question):

    """
    Creates a question-specific visualization.

    The chart is based on the exact business meaning
    of the submitted question.

    Examples:

    Which region has the lowest sales?
        -> Only the lowest region

    Which department has the highest average salary?
        -> Only the department with the highest average salary

    What are the top 2 regions by sales?
        -> Only top 2 regions
    """

    q = question.lower().strip()

    sales_column = detect_sales_column(df)
    region_column = detect_region_column(df)
    product_column = detect_product_column(df)
    segment_column = detect_segment_column(df)
    department_column = detect_department_column(df)
    salary_column = detect_salary_column(df)
    performance_column = detect_performance_column(df)

    question_type = detect_question_type(question)


    # =====================================================
    # DEPARTMENT + AVERAGE SALARY
    # =====================================================

    if (
        department_column
        and (
            "department" in q
            or "dept" in q
        )
    ):

        metric_column = salary_column

        # If salary is not detected, try numeric columns
        if not metric_column:

            numeric_columns = get_numeric_columns(df)

            if numeric_columns:

                # Prefer a column containing salary/pay
                salary_candidates = [
                    column
                    for column in numeric_columns
                    if any(
                        keyword in str(column).lower()
                        for keyword in [
                            "salary",
                            "income",
                            "pay"
                        ]
                    )
                ]

                if salary_candidates:

                    metric_column = (
                        salary_candidates[0]
                    )

                else:

                    metric_column = (
                        numeric_columns[0]
                    )

        if metric_column:

            data = df.copy()

            data[metric_column] = pd.to_numeric(
                data[metric_column],
                errors="coerce"
            )

            data = data.dropna(
                subset=[
                    department_column,
                    metric_column
                ]
            )

            if not data.empty:

                # -------------------------------------------------
                # Average salary / average metric
                # -------------------------------------------------

                if (
                    "average" in q
                    or "mean" in q
                    or "avg" in q
                ):

                    grouped = (
                        data
                        .groupby(
                            department_column
                        )[metric_column]
                        .mean()
                        .sort_values(
                            ascending=False
                        )
                    )

                    if not grouped.empty:

                        # Highest average
                        if question_type == "highest":

                            result = grouped.nlargest(1)

                            st.bar_chart(
                                result,
                                use_container_width=True
                            )

                            result_df = pd.DataFrame(
                                {
                                    "Department":
                                        result.index.astype(str),
                                    "Average":
                                        result.values
                                }
                            )

                            st.dataframe(
                                result_df,
                                use_container_width=True,
                                hide_index=True
                            )

                            department = (
                                result.index[0]
                            )

                            value = result.iloc[0]

                            st.success(
                                f"{department} has the "
                                f"highest average at "
                                f"{format_number(value)}."
                            )

                            return True

                        # Lowest average
                        if question_type == "lowest":

                            result = grouped.nsmallest(1)

                            st.bar_chart(
                                result,
                                use_container_width=True
                            )

                            result_df = pd.DataFrame(
                                {
                                    "Department":
                                        result.index.astype(str),
                                    "Average":
                                        result.values
                                }
                            )

                            st.dataframe(
                                result_df,
                                use_container_width=True,
                                hide_index=True
                            )

                            department = (
                                result.index[0]
                            )

                            value = result.iloc[0]

                            st.success(
                                f"{department} has the "
                                f"lowest average at "
                                f"{format_number(value)}."
                            )

                            return True

                        # General department average
                        result = grouped.head(20)

                        st.bar_chart(
                            result,
                            use_container_width=True
                        )

                        st.dataframe(
                            pd.DataFrame(
                                {
                                    "Department":
                                        result.index.astype(str),
                                    "Average":
                                        result.values
                                }
                            ),
                            use_container_width=True,
                            hide_index=True
                        )

                        return True


    # =====================================================
    # DEPARTMENT + TOTAL / SUM
    # =====================================================

    if (
        department_column
        and (
            "department" in q
            or "dept" in q
        )
        and salary_column
    ):

        data = df.copy()

        data[salary_column] = pd.to_numeric(
            data[salary_column],
