            region = result.index[0]
            value = result.iloc[0]

            st.success(
                f"{region} has the highest sales "
                f"at {format_number(value)}."
            )

            return True

        # -------------------------------------------------
        # Top N
        # -------------------------------------------------

        top_match = re.search(
            r"top\s+(\d+)",
            q
        )

        if top_match:

            n = int(
                top_match.group(1)
            )

            n = max(
