                        "Region":
                            result.index.astype(str),
                        "Total Sales":
                            result.values
                    }
                ),
                use_container_width=True,
                hide_index=True
            )

            return True

        # -------------------------------------------------
        # Normal region comparison
        # -------------------------------------------------

        if any(
            word in q
            for word in [
                "compare",
                "region",
                "sales by region"
            ]
        ):

            result = grouped.head(20)

            st.bar_chart(
                result,
                use_container_width=True
            )

            return True


    # =====================================================
    # PRODUCT + SALES
    # =====================================================

    if (
        product_column
        and sales_column
        and (
            "product" in q
            or "item" in q
        )
    ):

        data = df.copy()

        data[sales_column] = pd.to_numeric(
