            ]
        )

        grouped = (
            data
            .groupby(segment_column)[sales_column]
            .sum()
            .sort_values(
                ascending=False
            )
        )

        if grouped.empty:
            return False

        if question_type == "highest":

            result = grouped.nlargest(1)

        elif question_type == "lowest":

            result = grouped.nsmallest(1)

        else:

            result = grouped.head(20)

        st.bar_chart(
            result,
            use_container_width=True
        )

        st.dataframe(
            pd.DataFrame(
                {
                    "Segment":
                        result.index.astype(str),
                    "Sales":
                        result.values
                }
            ),
            use_container_width=True,
            hide_index=True
        )

        return True


    # =====================================================
    # PERFORMANCE + EMPLOYEE
    # =====================================================

    if (
        performance_column
        and (
            "performance" in q
            or "performance score" in q
        )
    ):

        data = df.copy()

        data[performance_column] = pd.to_numeric(
            data[performance_column],
            errors="coerce"
        )

        data = data.dropna(
            subset=[performance_column]
        )

        if not data.empty:

            # Try to find employee/name column
            employee_column = find_column(
                df,
                [
                    "employee",
                    "employee_name",
                    "name",
                    "employee_id",
                    "staff"
                ]
            )

            if (
                employee_column
                and question_type == "highest"
            ):

                result = data.nlargest(
                    1,
                    performance_column
                )

                employee = str(
                    result.iloc[0][employee_column]
                )

                value = result.iloc[0][
                    performance_column
                ]

                st.dataframe(
                    result[
                        [
                            employee_column,
                            performance_column
                        ]
                    ],
                    use_container_width=True,
                    hide_index=True
                )

                st.success(
                    f"{employee} has the highest "
                    f"performance score at "
                    f"{format_number(value)}."
                )

                return True

            if (
                employee_column
                and question_type == "lowest"
            ):

                result = data.nsmallest(
                    1,
                    performance_column
                )

                employee = str(
                    result.iloc[0][employee_column]
                )

                value = result.iloc[0][
                    performance_column
                ]

                st.dataframe(
                    result[
                        [
                            employee_column,
                            performance_column
                        ]
                    ],
                    use_container_width=True,
                    hide_index=True
                )

                st.success(
                    f"{employee} has the lowest "
                    f"performance score at "
                    f"{format_number(value)}."
                )

                return True


    # =====================================================
    # CORRELATION
    # =====================================================

    if "correlation" in q:

        numeric_columns = get_numeric_columns(df)

        if len(numeric_columns) >= 2:

            correlation = (
                df[numeric_columns]
                .corr()
                .round(2)
            )

            st.dataframe(
                correlation,
                use_container_width=True
            )

            return True


    # =====================================================
    # GENERAL COMPARISON OF NUMERIC VALUES
    # =====================================================

    if question_type == "comparison":

        numeric_columns = get_numeric_columns(df)

        if len(numeric_columns) >= 1:

            st.info(
                "A general comparison was requested. "
                "The verified calculation is shown above."
            )

            return False


    return False


# =========================================================
# BUSINESS INSIGHTS
# =========================================================

def build_business_facts(df):

    sales_column = detect_sales_column(df)
    quantity_column = detect_quantity_column(df)
    product_column = detect_product_column(df)
    region_column = detect_region_column(df)
    segment_column = detect_segment_column(df)

    facts = {}

    # -----------------------------------------------------
    # Sales
    # -----------------------------------------------------

    if sales_column:

        sales = safe_numeric_series(
            df,
            sales_column
        )

        if not sales.empty:

            facts["total_sales"] = sales.sum()
            facts["average_sales"] = sales.mean()
            facts["maximum_sales"] = sales.max()
            facts["minimum_sales"] = sales.min()

    # -----------------------------------------------------
    # Quantity
    # -----------------------------------------------------

    if quantity_column:

        quantity = safe_numeric_series(
            df,
            quantity_column
        )

        if not quantity.empty:

            facts["total_quantity"] = quantity.sum()

    # -----------------------------------------------------
    # Product
    # -----------------------------------------------------

    if (
        product_column
        and sales_column
    ):

        product_sales = (
            df.assign(
                __sales=pd.to_numeric(
                    df[sales_column],
                    errors="coerce"
                )
            )
            .groupby(product_column)["__sales"]
            .sum()
            .sort_values(
                ascending=False
            )
        )

        if not product_sales.empty:

            facts["top_product"] = str(
                product_sales.index[0]
            )

            facts["top_product_sales"] = (
                product_sales.iloc[0]
            )

    # -----------------------------------------------------
    # Region
    # -----------------------------------------------------

    if (
        region_column
        and sales_column
    ):

        region_sales = (
            df.assign(
                __sales=pd.to_numeric(
                    df[sales_column],
                    errors="coerce"
                )
            )
            .groupby(region_column)["__sales"]
            .sum()
            .sort_values(
                ascending=False
            )
        )

        if not region_sales.empty:

            facts["top_region"] = str(
                region_sales.index[0]
            )

            facts["top_region_sales"] = (
                region_sales.iloc[0]
            )

            facts["lowest_region"] = str(
                region_sales.index[-1]
            )

            facts["lowest_region_sales"] = (
                region_sales.iloc[-1]
            )

            facts["region_sales"] = (
                region_sales.to_dict()
            )

    # -----------------------------------------------------
    # Segment
    # -----------------------------------------------------

    if (
        segment_column
        and sales_column
    ):

        segment_sales = (
            df.assign(
                __sales=pd.to_numeric(
                    df[sales_column],
                    errors="coerce"
                )
            )
            .groupby(segment_column)["__sales"]
            .sum()
            .sort_values(
                ascending=False
            )
        )

        facts["segment_sales"] = (
            segment_sales.to_dict()
        )

    return facts


