def split_questions(text):

    if not text:
        return []

    text = text.replace("\r\n", "\n").strip()

    if not text:
        return []

    questions = []

    parts = re.split(r"\?", text)

    for part in parts:

        part = part.strip()

        if not part:
            continue

        part = re.sub(
            r"^\s*\d+\s*[\.\)\-:]\s*",
            "",
            part
        ).strip()

        if part:
            questions.append(
                part + "?"
            )

    if len(questions) <= 1:

        lines = [
            line.strip()
            for line in text.split("\n")
            if line.strip()
        ]

        if len(lines) > 1:

            questions = []

            for line in lines:

                line = re.sub(
                    r"^\s*\d+\s*[\.\)\-:]\s*",
                    "",
                    line
                ).strip()

                if not line:
                    continue

                if not line.endswith("?"):
                    line += "?"

                questions.append(line)

    return questions


def get_numeric_columns(df):

    return (
        df
        .select_dtypes(include=[np.number])
        .columns
        .tolist()
    )


def get_categorical_columns(df):

    categorical_types = [
        "object",
        "category",
        "bool",
        "string"
    ]

    return (
        df
        .select_dtypes(
            include=categorical_types
        )
        .columns
        .tolist()
    )


def get_date_columns(df):

    date_columns = []

    for column in df.columns:

        if pd.api.types.is_datetime64_any_dtype(
            df[column]
        ):

            date_columns.append(column)

        elif (
            pd.api.types.is_object_dtype(
                df[column]
            )
            or
            pd.api.types.is_string_dtype(
                df[column]
            )
        ):

            converted = pd.to_datetime(
                df[column],
                errors="coerce"
            )

            if (
                converted.notna().mean() >= 0.70
                and converted.notna().sum() > 0
            ):

                date_columns.append(column)

    return date_columns


def safe_numeric_series(df, column):

    if column not in df.columns:
        return pd.Series(dtype=float)

    return (
        pd.to_numeric(
            df[column],
            errors="coerce"
        )
        .replace(
            [np.inf, -np.inf],
            np.nan
        )
        .dropna()
    )


def format_number(value):

    if value is None:
        return "N/A"

    try:

        value = float(value)

        if math.isnan(value):
            return "N/A"

        if value.is_integer():
            return f"{int(value):,}"

        return f"{value:,.2f}"

    except Exception:

        return str(value)


def clean_dataframe(df):

    cleaned = df.copy()

    cleaned = cleaned.dropna(
        how="all"
    )

    cleaned = cleaned.dropna(
        axis=1,
        how="all"
    )

    cleaned.columns = [
        str(column).strip()
        for column in cleaned.columns
    ]

    seen = {}

    new_columns = []

    for column in cleaned.columns:

        if column not in seen:

            seen[column] = 0
            new_columns.append(column)

        else:

            seen[column] += 1

            new_columns.append(
                f"{column}_{seen[column]}"
            )

    cleaned.columns = new_columns

    return cleaned


# =========================================================
# COLUMN MATCHING
# =========================================================

def normalize_text(text):

    return (
        str(text)
        .strip()
        .lower()
        .replace("_", " ")
        .replace("-", " ")
    )


def find_column(df, candidates):

    normalized = {
        normalize_text(column): column
        for column in df.columns
    }

    for candidate in candidates:

        candidate_key = normalize_text(
            candidate
        )

        if candidate_key in normalized:
            return normalized[candidate_key]

    for column in df.columns:

        column_key = normalize_text(
            column
        )

        for candidate in candidates:

            candidate_key = normalize_text(
                candidate
            )

            if candidate_key in column_key:
                return column

    return None


