            "customer segment",
            "segment",
            "customer type"
        ]
    )


def detect_employee_column(df):

    return find_column(
        df,
        [
            "employee",
            "employee name",
            "name",
            "employee id"
        ]
    )


# =========================================================
# FIND QUESTION METRIC
# =========================================================

def detect_question_metric(df, question):

    q = normalize_text(question)

    if (
        "salary" in q
        or "salaries" in q
    ):

        column = detect_salary_column(df)

        if column:
            return column

    if (
        "sales" in q
        or "revenue" in q
    ):

        column = detect_sales_column(df)

        if column:
            return column

    if (
        "quantity" in q
        or "qty" in q
        or "units" in q
    ):

        column = detect_quantity_column(df)

        if column:
            return column

    for column in df.columns:

        column_words = normalize_text(
            column
        )

        if column_words in q:

            if column in get_numeric_columns(df):
                return column

    for column in df.columns:

        column_words = normalize_text(
            column
        )

        if (
            len(column_words) >= 3
            and column_words in q
            and column in get_numeric_columns(df)
        ):

            return column

    numeric_columns = get_numeric_columns(
        df
    )

    if len(numeric_columns) == 1:
        return numeric_columns[0]

    preferred = [
        "salary",
        "sales",
        "revenue",
        "amount",
        "income",
        "score",
        "performance",
        "quantity"
    ]

    for keyword in preferred:

        for column in numeric_columns:

            if keyword in normalize_text(
                column
            ):

                return column

    return None


# =========================================================
# FIND QUESTION CATEGORY
# =========================================================

def detect_question_category(df, question):

    q = normalize_text(question)

    category_columns = get_categorical_columns(
        df
    )

    keywords = {
        "region": [
            "region",
            "area",
            "territory",
            "zone"
        ],
        "department": [
            "department",
            "dept",
            "division"
        ],
        "product": [
            "product",
            "item"
        ],
        "segment": [
            "segment",
            "customer type"
        ],
        "employee": [
            "employee",
            "employee name",
            "name"
        ]
    }

    for _, words in keywords.items():

        for word in words:

            if word in q:

                for column in category_columns:

                    if word in normalize_text(
                        column
                    ):

                        return column

    for column in category_columns:

        column_name = normalize_text(
            column
        )

        if column_name in q:
            return column

    return None


# =========================================================
# QUESTION TYPE
# =========================================================

def detect_question_type(question):

    q = normalize_text(question)

    if re.search(
        r"\b(top|highest|maximum|most|best)\b",
        q
    ):
        return "highest"

    if re.search(
        r"\b(lowest|minimum|least|bottom)\b",
        q
    ):
        return "lowest"

    if re.search(
        r"\b(average|mean)\b",
        q
    ):
        return "average"

    if any(
        phrase in q
        for phrase in [
            "compare",
            "comparison",
            "versus",
            " vs ",
            "difference"
        ]
    ):
        return "comparison"

    if any(
        phrase in q
        for phrase in [
            "trend",
            "over time",
            "monthly",
            "daily",
            "weekly",
            "yearly"
        ]
    ):
        return "trend"

    if any(
        phrase in q
        for phrase in [
            "distribution",
            "spread"
        ]
    ):
        return "distribution"

    if any(
        phrase in q
        for phrase in [
            "correlation",
            "relationship",
            "related"
        ]
    ):
        return "correlation"

    if any(
        phrase in q
        for phrase in [
            "how many",
            "count",
            "number of"
        ]
    ):
        return "count"

    if any(
        phrase in q
        for phrase in [
            "total",
            "sum"
        ]
    ):
        return "total"

    if any(
        phrase in q
        for phrase in [
            "above",
            "greater than",
            "more than",
            "over",
            "below",
            "less than",
            "under"
        ]
    ):
        return "filter"

    return "general"


# =========================================================
# TOP N DETECTION
# =========================================================

def detect_top_n(question):

    match = re.search(
        r"\btop\s+(\d+)",
        question.lower()
    )

    if match:
        return int(match.group(1))

    return None


# =========================================================
# QUESTION VISUALIZATION
# =========================================================

def create_question_visualization(
    df,
    question
):

    q = normalize_text(question)

    question_type = detect_question_type(
        question
    )

    metric_column = detect_question_metric(
        df,
        question
    )

    category_column = detect_question_category(
        df,
        question
    )

    numeric_columns = get_numeric_columns(
        df
    )

    categorical_columns = get_categorical_columns(
        df
    )

    date_columns = get_date_columns(
        df
    )

    # =====================================================
    # CORRELATION
    # =====================================================

    if question_type == "correlation":

        if len(numeric_columns) < 2:
            return False

        correlation = (
            df[numeric_columns]
            .apply(
                pd.to_numeric,
                errors="coerce"
            )
            .corr()
            .round(2)
        )

        st.dataframe(
            correlation,
            width="stretch"
        )

        return True

    # =====================================================
    # TREND
    # =====================================================

    if question_type == "trend":

        if (
            not date_columns
            or not numeric_columns
        ):
            return False

        if metric_column is None:
            metric_column = numeric_columns[0]

        date_column = date_columns[0]

        trend_df = df.copy()

        trend_df[date_column] = pd.to_datetime(
            trend_df[date_column],
            errors="coerce"
        )

        trend_df[metric_column] = pd.to_numeric(
            trend_df[metric_column],
            errors="coerce"
        )

        trend_df = trend_df.dropna(
            subset=[
                date_column,
                metric_column
            ]
        )

        if trend_df.empty:
            return False

        trend_data = (
            trend_df
            .groupby(date_column)[metric_column]
            .sum()
            .sort_index()
        )

        st.line_chart(
            trend_data,
            width="stretch"
        )

        return True

    # =====================================================
    # NUMERIC METRIC WITHOUT CATEGORY
    # =====================================================

    if (
        metric_column
        and question_type in [
            "average",
            "total",
            "general",
            "distribution"
        ]
    ):

        series = safe_numeric_series(
            df,
            metric_column
        )

        if series.empty:
            return False

        if question_type == "average":

            value = series.mean()

            chart_data = pd.DataFrame(
                {
                    "Average": [value]
                }
            )

            st.bar_chart(
                chart_data,
                width="stretch"
            )

            st.success(
                f"Average {metric_column}: "
                f"{format_number(value)}"
            )

            return True

        if question_type == "total":

            value = series.sum()

            chart_data = pd.DataFrame(
                {
                    "Total": [value]
                }
            )

            st.bar_chart(
                chart_data,
                width="stretch"
            )

            st.success(
                f"Total {metric_column}: "
                f"{format_number(value)}"
            )

            return True

        if question_type == "distribution":

            if len(series) < 2:
                return False

            histogram = pd.cut(
                series,
                bins=10,
                duplicates="drop"
            ).value_counts(
                sort=False
            )

            histogram.index = (
                histogram.index.astype(str)
            )

            histogram_df = pd.DataFrame(
                {
                    "Frequency":
                        histogram.values
                },
                index=histogram.index
            )

            st.bar_chart(
                histogram_df,
                width="stretch"
            )

            return True

    # =====================================================
    # CATEGORY + NUMERIC METRIC
    # =====================================================

    if (
        metric_column
        and category_column
    ):

        if category_column not in df.columns:
            return False

        data = df.copy()

        data[metric_column] = pd.to_numeric(
            data[metric_column],
            errors="coerce"
        )

        data = data.dropna(
            subset=[
                category_column,
                metric_column
            ]
        )

        if data.empty:
            return False

        if question_type == "average":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .mean()
                .sort_values(
                    ascending=False
                )
            )

        elif question_type == "total":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

        elif question_type == "highest":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

            n = detect_top_n(
                question
            )

            if n is None:
                n = 1

            grouped = grouped.head(
                min(n, len(grouped))
            )

        elif question_type == "lowest":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=True
                )
            )

            n = detect_top_n(
                question
            )

            if n is None:
                n = 1

            grouped = grouped.head(
                min(n, len(grouped))
            )

        elif question_type == "comparison":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

        else:

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

        if grouped.empty:
            return False

        display_data = grouped.head(20)

        chart_df = pd.DataFrame(
            {
                metric_column:
                    display_data.values
            },
            index=display_data.index.astype(str)
        )

        st.bar_chart(
            chart_df,
            width="stretch"
        )

        result_table = pd.DataFrame(
            {
                str(category_column):
                    display_data.index.astype(str),
                str(metric_column):
                    display_data.values
            }
        )

        st.dataframe(
            result_table,
            width="stretch",
            hide_index=True
        )

        if question_type == "highest":

            first_category = display_data.index[0]
            first_value = display_data.iloc[0]

            st.success(
                f"{first_category} has the highest "
                f"{metric_column} at "
                f"{format_number(first_value)}."
            )

        elif question_type == "lowest":

            first_category = display_data.index[0]
            first_value = display_data.iloc[0]

            st.success(
                f"{first_category} has the lowest "
                f"{metric_column} at "
                f"{format_number(first_value)}."
            )

        return True

    # =====================================================
    # NUMERIC OVERVIEW FALLBACK
    # =====================================================

    if (
        metric_column
        and question_type in [
            "highest",
            "lowest"
        ]
    ):

        series = safe_numeric_series(
            df,
            metric_column
        )

        if series.empty:
            return False

        if question_type == "highest":
            value = series.max()
        else:
            value = series.min()

        chart_df = pd.DataFrame(
            {
                metric_column: [value]
            }
        )

        st.bar_chart(
            chart_df,
            width="stretch"
        )

        st.success(
            f"{question_type.title()} "
            f"{metric_column}: "
            f"{format_number(value)}"
        )

        return True

    # =====================================================
    # GENERIC NUMERIC FALLBACK
    # =====================================================

    if (
        len(numeric_columns) >= 1
        and question_type == "general"
    ):

        if metric_column:

            series = safe_numeric_series(
                df,
                metric_column
            )

            if not series.empty:

                st.bar_chart(
                    series.head(20),
                    width="stretch"
                )

                return True

    return False


# =========================================================
# BUSINESS FACTS
# =========================================================

def build_business_facts(df):

    facts = {}

    numeric_columns = get_numeric_columns(
        df
    )

    categorical_columns = get_categorical_columns(
        df
    )

    facts["rows"] = len(df)

    facts["columns"] = len(
        df.columns
    )

    facts["missing_values"] = int(
        df.isna().sum().sum()
    )

    facts["numeric_metrics"] = {}

    for column in numeric_columns:

        series = safe_numeric_series(
            df,
            column
        )

        if series.empty:
            continue

        facts["numeric_metrics"][column] = {
            "total": float(
                series.sum()
            ),
            "average": float(
                series.mean()
            ),
            "maximum": float(
                series.max()
            ),
            "minimum": float(
                series.min()
            ),
            "count": int(
                len(series)
            )
        }

    facts["category_summaries"] = {}

    for category in categorical_columns:

        if category not in df.columns:
            continue

        if df[category].nunique(
            dropna=True
        ) > 100:
            continue

        category_data = {}

        for metric in numeric_columns:

            temp = df.copy()

            temp[metric] = pd.to_numeric(
                temp[metric],
                errors="coerce"
            )

            grouped = (
                temp
                .groupby(category)[metric]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

            if not grouped.empty:

                category_data[metric] = {
                    str(k): float(v)
                    for k, v
                    in grouped.head(20).items()
                }

        if category_data:

            facts[
                "category_summaries"
            ][category] = category_data

    return facts


# =========================================================
# OLLAMA
# =========================================================

def call_ollama(
    prompt,
    timeout=60
):

    try:

        response = requests.post(
            "http://localhost:11434/api/generate",
            json={
                "model": "qwen2.5:3b",
                "prompt": prompt,
                "stream": False,
                "options": {
                    "temperature": 0.1,
                    "num_predict": 150
                }
            },
            timeout=timeout
        )

        if response.status_code != 200:

            return None, (
                f"Ollama returned HTTP "
                f"{response.status_code}: "
                f"{response.text}"
            )

        data = response.json()

        answer = (
            data
            .get("response", "")
            .strip()
        )

        if not answer:

            return None, (
                "Ollama returned an empty response."
            )

        return answer, None

    except requests.exceptions.ConnectionError:

        return None, (
            "Ollama is not running. "
            "Start Ollama and make sure the "
            "qwen2.5:3b model is available."
        )

    except requests.exceptions.Timeout:

        return None, (
            "Ollama took too long to respond."
        )

    except Exception as e:

        return None, str(e)


