    )

    st.dataframe(
        correlation_matrix.round(2),
        width="stretch"
    )

    correlation_pairs = []

    for i in range(
        len(correlation_matrix.columns)
    ):

        for j in range(
            i + 1,
            len(correlation_matrix.columns)
        ):

            column_a = (
                correlation_matrix
                .columns[i]
            )

            column_b = (
                correlation_matrix
                .columns[j]
            )

            value = (
                correlation_matrix
                .iloc[i, j]
            )

            if pd.notna(value):

                correlation_pairs.append(
                    (
                        column_a,
                        column_b,
                        value
                    )
                )

    if correlation_pairs:

        strongest_pair = max(
            correlation_pairs,
            key=lambda x: abs(x[2])
        )

        st.info(
            f"Strongest observed correlation: "
            f"{strongest_pair[0]} and "
            f"{strongest_pair[1]} "
            f"({strongest_pair[2]:.2f})"
