"""
    )


# =========================================================
# QUESTION FORM
# =========================================================

with st.form(
    "question_form",
    clear_on_submit=False
):

    user_question = st.text_area(
        "Your question:",
        placeholder=(
            "Example:\n"
            "Which department has the highest "
            "average salary?\n"
            "Compare IT and Finance salaries.\n"
            "What is the average salary?"
        ),
        height=160
    )

    ask_button = st.form_submit_button(
        "🚀 Ask"
    )


# =========================================================
# PROCESS QUESTIONS
# =========================================================

if (
    ask_button
    and
    user_question.strip()
):

    user_question = (
        user_question.strip()
    )

    questions = split_questions(
        user_question
    )

    if not questions:

        st.warning(
            "Please enter at least one question."
        )

        st.stop()


    # =====================================================
    # SAVE QUESTIONS
    # =====================================================

    st.session_state.last_questions = (
        questions
    )


    # =====================================================
    # VERIFIED CALCULATIONS
    # =====================================================

    verified_results = []

    with st.spinner(
        "🔎 Calculating verified answers..."
    ):

        for question in questions:

            try:

                verified_result = (
                    analyze_dataset(
                        df,
                        question
                    )
                )

            except Exception as e:

                verified_result = (
                    "Unable to calculate "
                    "this question: "
                    f"{e}"
                )

            verified_results.append(
                {
                    "question": question,
                    "verified": verified_result
                }
            )


    st.session_state.last_verified_results = (
        verified_results
    )


    # =====================================================
    # VERIFIED CALCULATIONS DISPLAY
    # =====================================================

    with st.expander(
        "🔍 Verified Calculations"
    ):

        for index, item in enumerate(
            verified_results,
            start=1
        ):

            st.markdown(
                f"### Question {index}"
            )

            st.write(
                item["question"]
            )

            st.code(
                str(
                    item["verified"]
                )
            )


    # =====================================================
    # BUILD VERIFIED CONTEXT
    # =====================================================

    verified_context_parts = []

    for index, item in enumerate(
        verified_results,
        start=1
    ):

        verified_context_parts.append(
            f"""
QUESTION {index}

USER QUESTION:
{item["question"]}

VERIFIED CALCULATION:
{item["verified"]}
"""
        )

    verified_context = (
        "\n".join(
            verified_context_parts
        )
    )


    # =====================================================
    # OLLAMA PROMPT
    # =====================================================

    prompt = f"""
You are an AI Data Analyst.

Answer every user question separately.

The application has already calculated
and verified the answers.

The VERIFIED CALCULATION is the
absolute source of truth.

IMPORTANT RULES:

1. Answer EVERY question.
2. Never skip a question.
3. Never ask for another question.
4. Do not recalculate anything.
5. Do not change any number.
6. Do not invent any number.
7. Do not invent missing information.
8. Use only the verified calculation
   belonging to that question.
9. Never mix answers between questions.
10. Preserve exact values.
11. If it is an average, call it an average.
12. If it is a total, call it a total.
13. If it is highest, identify the highest.
14. If it is lowest, identify the lowest.
15. If it is a comparison, explain the
    comparison using only the provided result.
16. If it is a list, preserve the list.
17. Keep each answer concise.
18. Do not mention Python.
19. Do not mention Ollama.
20. Do not mention the analysis engine.
21. Do not mention prompts.
22. Do not say information is missing if
    it exists in the verified calculation.

VERIFIED CALCULATIONS:

{verified_context}

FORMAT:

Question 1:
<direct answer>

Question 2:
<direct answer>

Question 3:
<direct answer>

Continue until every question is answered.

Return ONLY the answers.
"""


    # =====================================================
    # GET AI ANSWER
    # =====================================================

    with st.spinner(
        "🤖 Preparing AI answers..."
    ):

        answer, error = call_ollama(
            prompt
        )


    if error:

        st.error(
            error
        )

        st.warning(
            "Showing the verified calculations "
            "directly because the AI explanation "
            "could not be generated."
        )

        answer = "\n\n".join(
            [
                (
                    f"**Question {i}:**\n"
                    f"{item['verified']}"
                )
                for i, item in enumerate(
                    verified_results,
                    start=1
                )
            ]
        )

        st.markdown(
            answer
        )

    else:

        st.subheader(
            "🤖 AI Answer"
        )

        st.markdown(
            answer
        )


    # =====================================================
    # SAVE HISTORY
    # =====================================================

    st.session_state.chat_history.append(
        {
            "question": user_question,
            "answer": answer
        }
    )


    # =====================================================
    # QUESTION-SPECIFIC VISUALIZATION
    # =====================================================

    st.divider()

    st.header(
        "📊 Automatic Visualization"
    )

    visualization_created = False


    for index, question in enumerate(
        questions,
        start=1
    ):

        st.subheader(
            f"Question {index}"
        )

        st.caption(
            question
        )

        current_visualization = False


        # -------------------------------------------------
        # Generic visualization engine
        # -------------------------------------------------

        try:

            current_visualization = (
                create_question_visualization(
                    df,
                    question
                )
            )

        except Exception as e:

            current_visualization = False


        # -------------------------------------------------
        # Existing visual engine fallback
        # -------------------------------------------------

        if not current_visualization:

            try:

                current_visualization = (
                    generate_visual_analysis(
                        df,
                        question
                    )
                )

            except Exception:

                current_visualization = False


        if current_visualization:

            visualization_created = True

        else:

            st.info(
                "No automatic visualization is "
                "available for this question."
            )


    if not visualization_created:

        st.caption(
            "The visualization engine did not find "
            "a suitable chart for the submitted questions."
        )


# =========================================================
# ANALYSIS HISTORY
# =========================================================

if st.session_state.chat_history:

    st.divider()

    st.header(
        "🧠 Analysis History"
    )

    for index, chat in enumerate(
        reversed(
            st.session_state.chat_history
        ),
        start=1
    ):

        with st.expander(
            f"Analysis {index}: "
            f"{chat['question'][:80]}"
        ):

            st.markdown(
                f"**You:** "
                f"{chat['question']}"
            )

            st.markdown(
                "**🤖 AI:**"
            )

            st.markdown(
                chat["answer"]
            )


# =========================================================
# FOOTER
# =========================================================

st.divider()

st.caption(
    "📊 AI Data Analyst • "
    "Verified calculations + AI explanations + "
    "dataset-aware automatic visualization"
)
```

### What this fixes

The important change is that the application is **no longer built around sales**.

For example, with your salary/employee dataset:

**Question:**
> What is the average salary?

It detects `salary` → calculates the answer → creates a salary-specific visualization.

**Question:**
> Which department has the highest average salary?

It detects:

`department` → category  
`salary` → metric  
`highest` + `average` → operation

So it can produce a department/salary chart instead of incorrectly looking for regions/sales.

**Question:**
> Compare IT and Finance salaries.

It can use the `Department` + `Salary` relationship.

And for:

> Which region has the lowest sales?

It still works exactly as before.

So the architecture is now:

**User Question → Detect relevant metric/category → Verified calculation → AI explanation → Relevant visualization**

rather than:

**User Question → Assume Sales → Try to make Sales chart**

That was the main weakness in the previous version.

