# =========================================================
# GENERAL HELPERS
# =========================================================

def split_questions(text):

    if not text:
        return []

    text = text.replace("\r\n", "\n").strip()

    if not text:
        return []

    questions = []

    # Split by question mark
    parts = re.split(r"\?", text)

    for part in parts:

        part = part.strip()

        if not part:
            continue

        part = re.sub(
            r"^\s*\d+\s*[\.\)\-:]\s*",
            "",
            part
        ).strip()

        if part:
            questions.append(part + "?")

    # Multiline fallback
    if len(questions) <= 1:

        lines = [
            line.strip()
            for line in text.split("\n")
            if line.strip()
        ]

        if len(lines) > 1:

            questions = []

            for line in lines:

                line = re.sub(
                    r"^\s*\d+\s*[\.\)\-:]\s*",
                    "",
                    line
                ).strip()

                if not line:
                    continue

                if not line.endswith("?"):
                    line += "?"

                questions.append(line)

    return questions


def get_numeric_columns(df):

    return (
        df
        .select_dtypes(include=np.number)
        .columns
        .tolist()
    )


def get_categorical_columns(df):

    return (
        df
        .select_dtypes(
            include=["object", "category", "bool"]
        )
        .columns
        .tolist()
    )


def get_date_columns(df):

    date_columns = []

    for column in df.columns:

        if pd.api.types.is_datetime64_any_dtype(
            df[column]
        ):

            date_columns.append(column)

        elif df[column].dtype == "object":

            converted = pd.to_datetime(
                df[column],
                errors="coerce"
            )

            if (
                converted.notna().mean() >= 0.70
                and converted.notna().sum() > 0
            ):

                date_columns.append(column)

    return date_columns


def safe_numeric_series(df, column):

    if column not in df.columns:
        return pd.Series(dtype=float)

    return (
        pd.to_numeric(
            df[column],
            errors="coerce"
        )
        .replace(
            [np.inf, -np.inf],
            np.nan
        )
        .dropna()
    )


def format_number(value):

    if value is None:
        return "N/A"

    try:

        value = float(value)

        if math.isnan(value):
            return "N/A"

        if value.is_integer():
            return f"{int(value):,}"

        return f"{value:,.2f}"

    except Exception:

        return str(value)


def clean_dataframe(df):

    cleaned = df.copy()

    cleaned = cleaned.dropna(
        how="all"
    )

    cleaned = cleaned.dropna(
        axis=1,
        how="all"
    )

    cleaned.columns = [
        str(column).strip()
        for column in cleaned.columns
    ]

    # Handle duplicate column names
    seen = {}

    new_columns = []

    for column in cleaned.columns:

        if column not in seen:

            seen[column] = 0
            new_columns.append(column)

        else:

            seen[column] += 1

            new_columns.append(
                f"{column}_{seen[column]}"
            )

    cleaned.columns = new_columns

    return cleaned


# =========================================================
# COLUMN MATCHING
# =========================================================

def normalize_text(text):

    return (
        str(text)
        .strip()
        .lower()
        .replace("_", " ")
        .replace("-", " ")
    )


def find_column(df, candidates):

    normalized = {
        normalize_text(column): column
        for column in df.columns
    }

    # Exact match
    for candidate in candidates:

        candidate_key = normalize_text(
            candidate
        )

        if candidate_key in normalized:
            return normalized[candidate_key]

    # Partial match
    for column in df.columns:

        column_key = normalize_text(
            column
        )

        for candidate in candidates:

            candidate_key = normalize_text(
                candidate
            )

            if candidate_key in column_key:
                return column

    return None


# =========================================================
# BUSINESS COLUMN DETECTION
# =========================================================

def detect_sales_column(df):

    return find_column(
        df,
        [
            "sales",
            "revenue",
            "total sales",
            "total revenue",
            "sales amount",
            "revenue amount",
            "amount"
        ]
    )


def detect_salary_column(df):

    return find_column(
        df,
        [
            "salary",
            "salaries",
            "annual salary",
            "monthly salary",
            "pay",
            "income",
            "compensation"
        ]
    )


def detect_quantity_column(df):

    return find_column(
        df,
        [
            "quantity",
            "qty",
            "units",
            "units sold",
            "quantity sold"
        ]
    )


def detect_product_column(df):

    return find_column(
        df,
        [
            "product",
            "product name",
            "item",
            "item name"
        ]
    )


def detect_region_column(df):

    return find_column(
        df,
        [
            "region",
            "area",
            "territory",
            "zone"
        ]
    )


def detect_department_column(df):

    return find_column(
        df,
        [
            "department",
            "dept",
            "division",
            "business unit"
        ]
    )


def detect_segment_column(df):

    return find_column(
        df,
        [
            "customer segment",
            "segment",
            "customer type"
        ]
    )


def detect_employee_column(df):

    return find_column(
        df,
        [
            "employee",
            "employee name",
            "name",
            "employee id"
        ]
    )


# =========================================================
# FIND QUESTION METRIC
# =========================================================

def detect_question_metric(df, question):

    q = normalize_text(question)

    # Explicit business metrics
    if "salary" in q or "salaries" in q:

        column = detect_salary_column(df)

        if column:
            return column

    if (
        "sales" in q
        or "revenue" in q
    ):

        column = detect_sales_column(df)

        if column:
            return column

    if (
        "quantity" in q
        or "qty" in q
        or "units" in q
    ):

        column = detect_quantity_column(df)

        if column:
            return column

    # Exact column mentioned in question
    for column in df.columns:

        column_words = normalize_text(
            column
        )

        if column_words in q:
            if column in get_numeric_columns(df):
                return column

    # Partial column match
    for column in df.columns:

        column_words = normalize_text(
            column
        )

        if (
            len(column_words) >= 3
            and column_words in q
            and column in get_numeric_columns(df)
        ):
            return column

    # If only one numeric column exists
    numeric_columns = get_numeric_columns(df)

    if len(numeric_columns) == 1:
        return numeric_columns[0]

    # Common numeric preference
    preferred = [
        "salary",
        "sales",
        "revenue",
        "amount",
        "income",
        "score",
        "performance",
        "quantity"
    ]

    for keyword in preferred:

        for column in numeric_columns:

            if keyword in normalize_text(
                column
            ):

                return column

    return None


# =========================================================
# FIND QUESTION CATEGORY
# =========================================================

def detect_question_category(df, question):

    q = normalize_text(question)

    category_columns = get_categorical_columns(
        df
    )

    # Explicit category references
    keywords = {
        "region": [
            "region",
            "area",
            "territory",
            "zone"
        ],
        "department": [
            "department",
            "dept",
            "division"
        ],
        "product": [
            "product",
            "item"
        ],
        "segment": [
            "segment",
            "customer type"
        ],
        "employee": [
            "employee",
            "employee name",
            "name"
        ]
    }

    for _, words in keywords.items():

        for word in words:

            if word in q:

                for column in category_columns:

                    if word in normalize_text(
                        column
                    ):

                        return column

    # Match actual column names
    for column in category_columns:

        column_name = normalize_text(
            column
        )

        if column_name in q:
            return column

    return None


# =========================================================
# QUESTION TYPE
# =========================================================

def detect_question_type(question):

    q = normalize_text(question)

    if re.search(
        r"\b(top|highest|maximum|most|best)\b",
        q
    ):
        return "highest"

    if re.search(
        r"\b(lowest|minimum|least|bottom)\b",
        q
    ):
        return "lowest"

    if re.search(
        r"\b(average|mean)\b",
        q
    ):
        return "average"

    if any(
        phrase in q
        for phrase in [
            "compare",
            "comparison",
            "versus",
            " vs ",
            "difference"
        ]
    ):
        return "comparison"

    if any(
        phrase in q
        for phrase in [
            "trend",
            "over time",
            "monthly",
            "daily",
            "weekly",
            "yearly"
        ]
    ):
        return "trend"

    if any(
        phrase in q
        for phrase in [
            "distribution",
            "spread"
        ]
    ):
        return "distribution"

    if any(
        phrase in q
        for phrase in [
            "correlation",
            "relationship",
            "related"
        ]
    ):
        return "correlation"

    if any(
        phrase in q
        for phrase in [
            "how many",
            "count",
            "number of"
        ]
    ):
        return "count"

    if any(
        phrase in q
        for phrase in [
            "total",
            "sum"
        ]
    ):
        return "total"

    if any(
        phrase in q
        for phrase in [
            "above",
            "greater than",
            "more than",
            "over",
            "below",
            "less than",
            "under"
        ]
    ):
        return "filter"

    return "general"


# =========================================================
# TOP N DETECTION
# =========================================================

def detect_top_n(question):

    match = re.search(
        r"\btop\s+(\d+)",
        question.lower()
    )

    if match:

        return int(
            match.group(1)
        )

    return None


# =========================================================
# GENERIC QUESTION VISUALIZATION
# =========================================================

def create_question_visualization(
    df,
    question
):

    """
    Dataset-independent visualization engine.

    The chart is selected according to the question,
    not according to sales-specific assumptions.
    """

    q = normalize_text(
        question
    )

    question_type = detect_question_type(
        question
    )

    metric_column = detect_question_metric(
        df,
        question
    )

    category_column = detect_question_category(
        df,
        question
    )

    numeric_columns = get_numeric_columns(
        df
    )

    categorical_columns = get_categorical_columns(
        df
    )

    date_columns = get_date_columns(
        df
    )


    # =====================================================
    # CORRELATION
    # =====================================================

    if question_type == "correlation":

        if len(numeric_columns) < 2:

            return False

        correlation = (
            df[numeric_columns]
            .apply(
                pd.to_numeric,
                errors="coerce"
            )
            .corr()
            .round(2)
        )

        st.dataframe(
            correlation,
            use_container_width=True
        )

        return True


    # =====================================================
    # TREND
    # =====================================================

    if question_type == "trend":

        if (
            not date_columns
            or not numeric_columns
        ):

            return False

        if metric_column is None:

            metric_column = numeric_columns[0]

        date_column = date_columns[0]

        trend_df = df.copy()

        trend_df[date_column] = pd.to_datetime(
            trend_df[date_column],
            errors="coerce"
        )

        trend_df[metric_column] = pd.to_numeric(
            trend_df[metric_column],
            errors="coerce"
        )

        trend_df = trend_df.dropna(
            subset=[
                date_column,
                metric_column
            ]
        )

        if trend_df.empty:
            return False

        trend_data = (
            trend_df
            .groupby(date_column)[metric_column]
            .sum()
            .sort_index()
        )

        st.line_chart(
            trend_data,
            use_container_width=True
        )

        return True


    # =====================================================
    # NUMERIC METRIC WITHOUT CATEGORY
    # =====================================================

    if (
        metric_column
        and question_type in [
            "average",
            "total",
            "general",
            "distribution"
        ]
    ):

        series = safe_numeric_series(
            df,
            metric_column
        )

        if series.empty:
            return False

        # Average
        if question_type == "average":

            value = series.mean()

            chart_data = pd.DataFrame(
                {
                    "Average": [value]
                }
            )

            st.bar_chart(
                chart_data,
                use_container_width=True
            )

            st.success(
                f"Average {metric_column}: "
                f"{format_number(value)}"
            )

            return True

        # Total
        if question_type == "total":

            value = series.sum()

            chart_data = pd.DataFrame(
                {
                    "Total": [value]
                }
            )

            st.bar_chart(
                chart_data,
                use_container_width=True
            )

            st.success(
                f"Total {metric_column}: "
                f"{format_number(value)}"
            )

            return True

        # Distribution
        if question_type == "distribution":

            if len(series) < 2:
                return False

            histogram = pd.cut(
                series,
                bins=10,
                duplicates="drop"
            ).value_counts(
                sort=False
            )

            histogram.index = (
                histogram.index.astype(str)
            )

            histogram_df = pd.DataFrame(
                {
                    "Frequency":
                        histogram.values
                },
                index=histogram.index
            )

            st.bar_chart(
                histogram_df,
                use_container_width=True
            )

            return True


    # =====================================================
    # CATEGORY + NUMERIC METRIC
    # =====================================================

    if (
        metric_column
        and category_column
    ):

        if category_column not in df.columns:
            return False

        data = df.copy()

        data[metric_column] = pd.to_numeric(
            data[metric_column],
            errors="coerce"
        )

        data = data.dropna(
            subset=[
                category_column,
                metric_column
            ]
        )

        if data.empty:
            return False


        # -------------------------------------------------
        # GROUPED AVERAGE
        # -------------------------------------------------

        if question_type == "average":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .mean()
                .sort_values(
                    ascending=False
                )
            )

        # -------------------------------------------------
        # GROUPED TOTAL
        # -------------------------------------------------

        elif question_type == "total":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

        # -------------------------------------------------
        # HIGHEST
        # -------------------------------------------------

        elif question_type == "highest":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

            n = detect_top_n(
                question
            )

            if n is None:
                n = 1

            grouped = grouped.head(
                min(n, len(grouped))
            )

        # -------------------------------------------------
        # LOWEST
        # -------------------------------------------------

        elif question_type == "lowest":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=True
                )
            )

            n = detect_top_n(
                question
            )

            if n is None:
                n = 1

            grouped = grouped.head(
                min(n, len(grouped))
            )

        # -------------------------------------------------
        # COMPARISON
        # -------------------------------------------------

        elif question_type == "comparison":

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

        # -------------------------------------------------
        # GENERAL
        # -------------------------------------------------

        else:

            grouped = (
                data
                .groupby(category_column)[
                    metric_column
                ]
                .sum()
                .sort_values(
                    ascending=False
                )
            )


        if grouped.empty:
            return False


        # Limit huge categories
        display_data = grouped.head(
            20
        )

        chart_df = pd.DataFrame(
            {
                metric_column:
                    display_data.values
            },
            index=display_data.index.astype(str)
        )

        st.bar_chart(
            chart_df,
            use_container_width=True
        )


        # Result table
        result_table = pd.DataFrame(
            {
                str(category_column):
                    display_data.index.astype(str),
                str(metric_column):
                    display_data.values
            }
        )

        st.dataframe(
            result_table,
            use_container_width=True,
            hide_index=True
        )


        # Highest / lowest explanation
        if question_type == "highest":

            first_category = display_data.index[0]
            first_value = display_data.iloc[0]

            st.success(
                f"{first_category} has the highest "
                f"{metric_column} at "
                f"{format_number(first_value)}."
            )

        elif question_type == "lowest":

            first_category = display_data.index[0]
            first_value = display_data.iloc[0]

            st.success(
                f"{first_category} has the lowest "
                f"{metric_column} at "
                f"{format_number(first_value)}."
            )

        return True


    # =====================================================
    # NUMERIC OVERVIEW FALLBACK
    # =====================================================

    if (
        metric_column
        and question_type in [
            "highest",
            "lowest"
        ]
    ):

        series = safe_numeric_series(
            df,
            metric_column
        )

        if series.empty:
            return False

        if question_type == "highest":

            value = series.max()

        else:

            value = series.min()

        chart_df = pd.DataFrame(
            {
                metric_column: [value]
            }
        )

        st.bar_chart(
            chart_df,
            use_container_width=True
        )

        st.success(
            f"{question_type.title()} "
            f"{metric_column}: "
            f"{format_number(value)}"
        )

        return True


    # =====================================================
    # GENERIC NUMERIC FALLBACK
    # =====================================================

    if (
        len(numeric_columns) >= 1
        and question_type == "general"
    ):

        if metric_column:

            series = safe_numeric_series(
                df,
                metric_column
            )

            if not series.empty:

                st.bar_chart(
                    series.head(20),
                    use_container_width=True
                )

                return True

    return False


# =========================================================
# BUSINESS FACTS
# =========================================================

def build_business_facts(df):

    facts = {}

    numeric_columns = get_numeric_columns(
        df
    )

    categorical_columns = get_categorical_columns(
        df
    )

    facts["rows"] = len(df)

    facts["columns"] = len(
        df.columns
    )

    facts["missing_values"] = int(
        df.isna().sum().sum()
    )

    # Numeric metrics
    facts["numeric_metrics"] = {}

    for column in numeric_columns:

        series = safe_numeric_series(
            df,
            column
        )

        if series.empty:
            continue

        facts["numeric_metrics"][column] = {
            "total": float(
                series.sum()
            ),
            "average": float(
                series.mean()
            ),
            "maximum": float(
                series.max()
            ),
            "minimum": float(
                series.min()
            ),
            "count": int(
                len(series)
            )
        }


    # Category summaries
    facts["category_summaries"] = {}

    for category in categorical_columns:

        if category not in df.columns:
            continue

        # Only reasonable cardinality
        if df[category].nunique(
            dropna=True
        ) > 100:
            continue

        category_data = {}

        for metric in numeric_columns:

            temp = df.copy()

            temp[metric] = pd.to_numeric(
                temp[metric],
                errors="coerce"
            )

            grouped = (
                temp
                .groupby(category)[metric]
                .sum()
                .sort_values(
                    ascending=False
                )
            )

            if not grouped.empty:

                category_data[metric] = {
                    str(k): float(v)
                    for k, v
                    in grouped.head(20).items()
                }

        if category_data:

            facts[
                "category_summaries"
            ][category] = category_data

    return facts


# =========================================================
# OLLAMA
# =========================================================

def call_ollama(
    prompt,
    timeout=120
):

    try:

        response = requests.post(
            "http://localhost:11434/api/generate",
            json={
                "model": "llama3",
                "prompt": prompt,
                "stream": False,
                "options": {
                    "temperature": 0.1
                }
            },
            timeout=timeout
        )

        if response.status_code != 200:

            return None, (
                f"Ollama returned HTTP "
                f"{response.status_code}: "
                f"{response.text}"
            )

        data = response.json()

        answer = (
            data
            .get("response", "")
            .strip()
        )

        if not answer:

            return None, (
                "Ollama returned an empty response."
            )

        return answer, None

    except requests.exceptions.ConnectionError:

        return None, (
            "Ollama is not running. "
            "Start Ollama and make sure the "
            "llama3 model is available."
        )

    except requests.exceptions.Timeout:

        return None, (
            "Ollama took too long to respond."
        )

    except Exception as e:

        return None, str(e)


