def format_number(value):

    if value is None:
        return "N/A"

    try:

        value = float(value)

        if math.isnan(value):
            return "N/A"

        if value.is_integer():
            return f"{int(value):,}"

        return f"{value:,.2f}"

    except Exception:

        return str(value)


def clean_dataframe(df):

    cleaned = df.copy()

    # Remove completely empty rows
    cleaned = cleaned.dropna(
        how="all"
    )

    # Remove completely empty columns
    cleaned = cleaned.dropna(
        axis=1,
        how="all"
    )

    # Clean column names
    cleaned.columns = [
        str(column).strip()
        for column in cleaned.columns
    ]

    # Remove duplicate column names safely
    seen = {}

    new_columns = []

    for column in cleaned.columns:

        if column not in seen:

            seen[column] = 0
            new_columns.append(column)

        else:

            seen[column] += 1

            new_columns.append(
                f"{column}_{seen[column]}"
            )

    cleaned.columns = new_columns

    return cleaned


def call_ollama(prompt, timeout=120):

    try:

        response = requests.post(
            "http://localhost:11434/api/generate",
            json={
                "model": "llama3",
                "prompt": prompt,
                "stream": False,
                "options": {
                    "temperature": 0.1
                }
            },
            timeout=timeout
        )

        if response.status_code != 200:

            return None, (
                f"Ollama returned HTTP "
                f"{response.status_code}: "
                f"{response.text}"
            )

        data = response.json()

        answer = (
            data
            .get("response", "")
            .strip()
        )

        if not answer:

            return None, (
                "Ollama returned an empty response."
            )

        return answer, None

    except requests.exceptions.ConnectionError:

        return None, (
            "Ollama is not running. "
            "Start Ollama and make sure the llama3 model is available."
        )

    except requests.exceptions.Timeout:

        return None, (
            "Ollama took too long to respond."
        )

    except Exception as e:

        return None, str(e)


# =========================================================
# QUESTION TYPE DETECTION
# =========================================================

def detect_question_type(question):

    q = question.lower().strip()

    if any(
        phrase in q
        for phrase in [
            "top ",
            "highest",
            "maximum",
            "most",
            "best"
        ]
    ):
        return "highest"

    if any(
        phrase in q
        for phrase in [
            "lowest",
            "minimum",
            "least",
            "bottom"
        ]
    ):
        return "lowest"

    if any(
        phrase in q
        for phrase in [
            "average",
            "mean"
        ]
    ):
        return "average"

    if any(
        phrase in q
        for phrase in [
            "compare",
            "comparison",
            "versus",
            " vs ",
            "difference"
        ]
    ):
        return "comparison"

    if any(
        phrase in q
        for phrase in [
            "trend",
            "over time",
            "monthly",
            "daily",
            "weekly",
            "yearly"
        ]
    ):
        return "trend"

    if any(
        phrase in q
        for phrase in [
            "distribution",
            "spread"
        ]
    ):
        return "distribution"

    if any(
        phrase in q
        for phrase in [
            "correlation",
            "relationship",
            "related"
        ]
    ):
        return "correlation"

    return "general"


# =========================================================
# DIRECT QUESTION VISUALIZATION
# =========================================================

def create_question_visualization(df, question):

    """
    Creates a question-specific chart.

    This is intentionally handled here as a fallback so
    questions such as:

        Which region has the lowest sales?

    do not accidentally display every region as the answer.
    """

    q = question.lower()

    sales_column = detect_sales_column(df)
    region_column = detect_region_column(df)
    product_column = detect_product_column(df)
    segment_column = detect_segment_column(df)

    # -----------------------------------------------------
    # Region + Sales
    # -----------------------------------------------------

    if (
        region_column
        and sales_column
        and (
            "region" in q
            or "area" in q
            or "territory" in q
        )
    ):

        data = df.copy()

        data[sales_column] = pd.to_numeric(
            data[sales_column],
            errors="coerce"
        )

        data = data.dropna(
            subset=[
                region_column,
                sales_column
            ]
        )

        grouped = (
            data
            .groupby(region_column)[sales_column]
            .sum()
            .sort_values(ascending=False)
        )

        if grouped.empty:
            return False

        question_type = detect_question_type(question)

        # -------------------------------------------------
        # Lowest
        # -------------------------------------------------

        if question_type == "lowest":

            result = grouped.nsmallest(1)

            st.bar_chart(
                result,
                use_container_width=True
            )

            st.dataframe(
                pd.DataFrame(
                    {
                        "Region":
                            result.index.astype(str),
                        "Total Sales":
                            result.values
                    }
                ),
                use_container_width=True,
                hide_index=True
            )

            region = result.index[0]
            value = result.iloc[0]

            st.success(
                f"{region} has the lowest sales "
                f"at {format_number(value)}."
            )

            return True

        # -------------------------------------------------
        # Highest
        # -------------------------------------------------

        if question_type == "highest":

            result = grouped.nlargest(1)

            st.bar_chart(
                result,
                use_container_width=True
            )

            st.dataframe(
                pd.DataFrame(
                    {
                        "Region":
                            result.index.astype(str),
                        "Total Sales":
                            result.values
                    }
                ),
                use_container_width=True,
                hide_index=True
            )

            region = result.index[0]
            value = result.iloc[0]

            st.success(
                f"{region} has the highest sales "
                f"at {format_number(value)}."
            )

            return True

        # -------------------------------------------------
        # Top N
        # -------------------------------------------------

        top_match = re.search(
            r"top\s+(\d+)",
            q
        )

        if top_match:

            n = int(
                top_match.group(1)
            )

            n = max(
                1,
                min(n, len(grouped))
            )

            result = grouped.head(n)

            st.bar_chart(
                result,
                use_container_width=True
            )

            st.dataframe(
                pd.DataFrame(
                    {
                        "Region":
                            result.index.astype(str),
                        "Total Sales":
                            result.values
                    }
                ),
                use_container_width=True,
                hide_index=True
            )

            return True

        # -------------------------------------------------
        # Normal region comparison
        # -------------------------------------------------

        if any(
            word in q
            for word in [
                "compare",
                "region",
                "sales by region"
            ]
        ):

            result = grouped.head(20)

            st.bar_chart(
                result,
                use_container_width=True
            )

            return True


    # =====================================================
    # Product + Sales
    # =====================================================

    if (
        product_column
        and sales_column
        and (
            "product" in q
            or "item" in q
        )
    ):

        data = df.copy()

        data[sales_column] = pd.to_numeric(
            data[sales_column],
            errors="coerce"
        )

        data = data.dropna(
            subset=[
                product_column,
                sales_column
            ]
        )

        grouped = (
            data
            .groupby(product_column)[sales_column]
            .sum()
            .sort_values(ascending=False)
        )

        if grouped.empty:
            return False

        question_type = detect_question_type(question)

        if question_type == "lowest":

            result = grouped.nsmallest(1)

        elif question_type == "highest":

            result = grouped.nlargest(1)

        else:

            result = grouped.head(10)

        st.bar_chart(
            result,
            use_container_width=True
        )

        st.dataframe(
            pd.DataFrame(
                {
                    "Product":
                        result.index.astype(str),
                    "Sales":
                        result.values
                }
            ),
            use_container_width=True,
            hide_index=True
        )

        return True


    # =====================================================
    # Segment + Sales
    # =====================================================

    if (
        segment_column
        and sales_column
        and "segment" in q
    ):

        data = df.copy()

        data[sales_column] = pd.to_numeric(
            data[sales_column],
            errors="coerce"
        )

        data = data.dropna(
            subset=[
                segment_column,
                sales_column
            ]
        )

        grouped = (
            data
            .groupby(segment_column)[sales_column]
            .sum()
            .sort_values(ascending=False)
        )

        if grouped.empty:
            return False

        st.bar_chart(
            grouped.head(20),
            use_container_width=True
        )

        return True


    # =====================================================
    # Correlation
    # =====================================================

    if "correlation" in q:

        numeric_columns = get_numeric_columns(df)

        if len(numeric_columns) >= 2:

            correlation = (
                df[numeric_columns]
                .corr()
                .round(2)
            )

            st.dataframe(
                correlation,
                use_container_width=True
            )

            return True


    return False


# =========================================================
# BUSINESS INSIGHTS
# =========================================================

def build_business_facts(df):

    sales_column = detect_sales_column(df)
    quantity_column = detect_quantity_column(df)
    product_column = detect_product_column(df)
    region_column = detect_region_column(df)
    segment_column = detect_segment_column(df)

    facts = {}

    # -----------------------------------------------------
    # Sales
    # -----------------------------------------------------

    if sales_column:

        sales = safe_numeric_series(
            df,
            sales_column
        )

        if not sales.empty:

            facts["total_sales"] = sales.sum()
            facts["average_sales"] = sales.mean()
            facts["maximum_sales"] = sales.max()
            facts["minimum_sales"] = sales.min()

    # -----------------------------------------------------
    # Quantity
    # -----------------------------------------------------

    if quantity_column:

        quantity = safe_numeric_series(
            df,
            quantity_column
        )

        if not quantity.empty:

            facts["total_quantity"] = quantity.sum()

    # -----------------------------------------------------
    # Product
    # -----------------------------------------------------

    if (
        product_column
        and sales_column
    ):

        product_sales = (
            df.assign(
                __sales=pd.to_numeric(
                    df[sales_column],
                    errors="coerce"
                )
            )
            .groupby(product_column)["__sales"]
            .sum()
            .sort_values(ascending=False)
        )

        if not product_sales.empty:

            facts["top_product"] = str(
                product_sales.index[0]
            )

            facts["top_product_sales"] = (
                product_sales.iloc[0]
            )

    # -----------------------------------------------------
    # Region
    # -----------------------------------------------------

    if (
        region_column
        and sales_column
    ):

        region_sales = (
            df.assign(
                __sales=pd.to_numeric(
                    df[sales_column],
                    errors="coerce"
                )
            )
            .groupby(region_column)["__sales"]
            .sum()
            .sort_values(ascending=False)
        )

        if not region_sales.empty:

            facts["top_region"] = str(
                region_sales.index[0]
            )

            facts["top_region_sales"] = (
                region_sales.iloc[0]
            )

            facts["lowest_region"] = str(
                region_sales.index[-1]
            )

            facts["lowest_region_sales"] = (
                region_sales.iloc[-1]
            )

            facts["region_sales"] = (
                region_sales.to_dict()
            )

    # -----------------------------------------------------
    # Segment
    # -----------------------------------------------------

    if (
        segment_column
        and sales_column
    ):

        segment_sales = (
            df.assign(
                __sales=pd.to_numeric(
                    df[sales_column],
                    errors="coerce"
                )
            )
            .groupby(segment_column)["__sales"]
            .sum()
            .sort_values(ascending=False)
        )

        facts["segment_sales"] = (
            segment_sales.to_dict()
        )

    return facts


