        outlier_metric
    )

    if len(outlier_series) >= 4:

        q1 = outlier_series.quantile(0.25)
        q3 = outlier_series.quantile(0.75)

        iqr = q3 - q1

        lower_bound = q1 - 1.5 * iqr
        upper_bound = q3 + 1.5 * iqr

        outliers = outlier_series[
            (
                outlier_series < lower_bound
            )
            |
            (
                outlier_series > upper_bound
            )
        ]

        c1, c2, c3 = st.columns(3)

        with c1:

            st.metric(
                "Outliers",
                f"{len(outliers):,}"
            )

        with c2:

            st.metric(
                "Lower Bound",
                format_number(
                    lower_bound
                )
            )

        with c3:

            st.metric(
                "Upper Bound",
                format_number(
                    upper_bound
                )
            )

        if not outliers.empty:

            st.dataframe(
                outliers.to_frame(
                    name=outlier_metric
                ).head(20),
                use_container_width=True
            )

        else:

            st.success(
                "No statistical outliers were detected."
            )


# =========================================================
# CORRELATION ANALYSIS
# =========================================================

if len(numeric_columns) >= 2:

    st.subheader(
        "🔗 Correlation Analysis"
    )

    correlation_matrix = (
        df[numeric_columns]
        .apply(
            pd.to_numeric,
            errors="coerce"
        )
        .corr()
    )

    st.dataframe(
        correlation_matrix.round(2),
        use_container_width=True
    )

    correlation_pairs = []

    for i in range(
        len(correlation_matrix.columns)
    ):

        for j in range(
            i + 1,
            len(correlation_matrix.columns)
        ):

            column_a = (
                correlation_matrix.columns[i]
            )

            column_b = (
                correlation_matrix.columns[j]
            )

            value = correlation_matrix.iloc[
                i,
                j
            ]

            if pd.notna(value):

                correlation_pairs.append(
                    (
                        column_a,
                        column_b,
                        value
                    )
                )

    if correlation_pairs:

        strongest_pair = max(
            correlation_pairs,
            key=lambda x: abs(x[2])
        )

        st.info(
            f"Strongest observed correlation: "
            f"{strongest_pair[0]} and "
            f"{strongest_pair[1]} "
            f"({strongest_pair[2]:.2f})"
        )


# =========================================================
# NUMERIC METRICS OVERVIEW
# =========================================================

if numeric_columns:

    st.subheader(
