### What this replaces

**Replace the entire contents of `app.py`** with the code above. You don't need to merge individual sections.

The important fix for the issue you showed is this part:

- **“Which region has the lowest sales?”** → chart shows **only West**
- **“Which region has the highest sales?”** → chart shows **only North**
- **“Top 2 regions by sales”** → chart shows **North + South**
- **“Compare sales by region”** → chart can show all regions
- The verified calculation remains the source of truth.
- If Ollama fails, the verified calculation is still shown instead of the whole feature failing.

So yes — **this is the one-shot app.py replacement**, rather than us continuing through the same changes one by one.

Absolutely. 🔥 Replace your **entire `visual_analysis.py`** with this version.

This version keeps your working **North vs South** comparison and adds intelligent chart selection:

- 📊 Bar → comparisons, rankings, totals, averages
- 📈 Line → trends / time-based questions
- 🥧 Pie → percentage/share questions
- 🔵 Scatter → relationships between two numeric columns
- Generic fallback for other datasets
- Works with different dataset column names
- No hard-coded North/South logic

```python
import re
import pandas as pd
import streamlit as st


# =========================================================
# NORMALIZATION
# =========================================================

def _normalize(value):
    return re.sub(
        r"\s+",
        " ",
        str(value).strip().lower()
    )


def _clean_columns(df):
    df = df.copy()

    df.columns = [
        str(column).strip()
        for column in df.columns
    ]

    return df


# =========================================================
# COLUMN DETECTION
# =========================================================

def _find_column(df, candidates):

    normalized = {
        _normalize(column)
        .replace(" ", "")
        .replace("_", ""): column
        for column in df.columns
    }

    # Exact match
    for candidate in candidates:

        key = (
            _normalize(candidate)
            .replace(" ", "")
            .replace("_", "")
        )

        if key in normalized:
            return normalized[key]

    # Partial match
    for column in df.columns:

        column_key = (
            _normalize(column)
            .replace(" ", "")
            .replace("_", "")
        )

        for candidate in candidates:

            candidate_key = (
                _normalize(candidate)
                .replace(" ", "")
                .replace("_", "")
            )

            if (
                candidate_key
                and candidate_key in column_key
            ):
                return column

    return None


def _numeric_columns(df):

    return (
        df
        .select_dtypes(
            include="number"
        )
        .columns
        .tolist()
    )


def _categorical_columns(df):

    return (
        df
        .select_dtypes(
            include=[
                "object",
                "category",
                "string"
            ]
        )
        .columns
        .tolist()
    )


def _date_columns(df):

    columns = []

    for column in df.columns:

        # Already datetime
        if pd.api.types.is_datetime64_any_dtype(
            df[column]
        ):
            columns.append(column)
            continue

        # Try converting object/string columns
        if (
            df[column].dtype == "object"
            or str(df[column].dtype) == "string"
        ):

            converted = pd.to_datetime(
                df[column],
                errors="coerce"
            )

            valid_ratio = (
                converted.notna().mean()
            )

            if valid_ratio >= 0.7:
                columns.append(column)

    return columns


# =========================================================
# QUESTION DETECTION
# =========================================================

def _comparison_requested(question):

    q = _normalize(question)

    patterns = [
        r"\bcompare\b",
        r"\bcomparison\b",
        r"\bversus\b",
        r"\bvs\b",
        r"\bdifference between\b",
        r"\bcompare between\b",
    ]

    return any(
        re.search(
            pattern,
            q
        )
        for pattern in patterns
    )


def _average_requested(question):

    q = _normalize(question)

    return any(
        word in q
        for word in (
            "average",
            "avg",
            "mean",
        )
    )


def _total_requested(question):

    q = _normalize(question)

    return any(
        word in q
        for word in (
            "total",
            "sum",
            "overall",
        )
    )


def _highest_requested(question):

    q = _normalize(question)

    return any(
        word in q
        for word in (
            "highest",
            "maximum",
            "max",
            "top",
            "most",
            "best",
        )
    )


def _lowest_requested(question):

    q = _normalize(question)

    return any(
        word in q
        for word in (
            "lowest",
            "minimum",
            "min",
            "least",
            "worst",
            "smallest",
        )
    )


def _trend_requested(question):

    q = _normalize(question)

    phrases = (
        "trend",
        "over time",
        "time series",
        "monthly trend",
        "daily trend",
        "weekly trend",
        "yearly trend",
        "annual trend",
        "monthly",
        "daily",
        "weekly",
        "yearly",
        "annual",
        "growth over time",
        "sales over time",
        "revenue over time",
        "performance over time",
    )

    return any(
        phrase in q
        for phrase in phrases
    )


def _share_requested(question):

    q = _normalize(question)

    phrases = (
        "percentage",
        "percent",
        "share",
        "proportion",
        "percentage of",
        "share of",
        "distribution",
    )

    return any(
        phrase in q
        for phrase in phrases
    )


def _relationship_requested(question):

    q = _normalize(question)

    phrases = (
        "relationship",
        "correlation",
        "relationship between",
        "correlation between",
        "against",
    )

    return any(
        phrase in q
        for phrase in phrases
    )


# =========================================================
# NUMERIC CONVERSION
# =========================================================

def _numeric(df, column):

    return pd.to_numeric(
        df[column],
        errors="coerce"
    )


# =========================================================
# FIND METRIC COLUMN
# =========================================================

def _find_metric_column(
    df,
    question
):

    q = _normalize(question)

    numeric_columns = _numeric_columns(
        df
    )

    if not numeric_columns:
        return None

    # -----------------------------------------------------
    # Exact / partial column-name matching
    # -----------------------------------------------------

    for column in numeric_columns:

        column_text = _normalize(
            column
        )

        variants = [
            column_text,
            column_text.replace(
                "_",
                " "
            ),
            column_text.replace(
                "_",
                ""
            ),
        ]

        for variant in variants:

            if (
                variant
                and variant in q
            ):
                return column

    # -----------------------------------------------------
    # Business aliases
    # -----------------------------------------------------

    aliases = {
        "sales": [
            "sales",
            "revenue",
            "turnover",
        ],

        "revenue": [
            "revenue",
            "sales",
            "turnover",
        ],

        "salary": [
            "salary",
            "salaries",
            "pay",
            "wage",
            "income",
            "compensation",
        ],

        "profit": [
            "profit",
            "profits",
            "margin",
        ],

        "quantity": [
            "quantity",
            "units",
            "volume",
        ],

        "performance": [
            "performance",
            "score",
            "rating",
        ],

        "experience": [
            "experience",
            "years",
            "tenure",
        ],

        "age": [
            "age",
        ],

        "cost": [
            "cost",
            "expense",
            "expenses",
        ],
    }

    for column in numeric_columns:

        column_text = _normalize(
            column
        )

        for key, words in aliases.items():

            if key in column_text:

                if any(
                    word in q
                    for word in words
                ):
                    return column

    # -----------------------------------------------------
    # One numeric column = safest fallback
    # -----------------------------------------------------

    if len(numeric_columns) == 1:
        return numeric_columns[0]

    return None


# =========================================================
# FIND SECOND NUMERIC METRIC
# =========================================================

def _find_second_metric_column(
    df,
    question,
    first_metric=None
):

    q = _normalize(question)

    numeric_columns = _numeric_columns(
        df
    )

    candidates = [
        column
        for column in numeric_columns
        if column != first_metric
    ]

    if not candidates:
        return None

    # Explicit column mentioned
    for column in candidates:

        column_text = _normalize(
            column
        )

        variants = [
            column_text,
            column_text.replace(
                "_",
                " "
            ),
            column_text.replace(
                "_",
                ""
            ),
        ]

        if any(
            variant
            and variant in q
            for variant in variants
        ):
            return column

    # Common aliases
    aliases = {
        "sales": [
            "sales",
            "revenue",
        ],

        "profit": [
            "profit",
            "margin",
        ],

        "salary": [
            "salary",
            "pay",
        ],

        "cost": [
            "cost",
            "expense",
        ],

        "quantity": [
            "quantity",
            "units",
        ],

        "performance": [
            "performance",
            "score",
            "rating",
        ],
    }

    for column in candidates:

        column_text = _normalize(
            column
        )

        for key, words in aliases.items():

            if key in column_text:

                if any(
                    word in q
                    for word in words
                ):
                    return column

    return None


# =========================================================
# FIND DIMENSION COLUMN
# =========================================================

def _find_dimension_column(
    df,
    question,
    mentioned_values=None
):

    categorical_columns = (
        _categorical_columns(df)
    )

    if not categorical_columns:
        return None

    q = _normalize(question)

    # -----------------------------------------------------
    # Explicit column name
    # -----------------------------------------------------

    for column in categorical_columns:

        column_text = _normalize(
            column
        )

        variants = [
            column_text,
            column_text.replace(
                "_",
                " "
            ),
            column_text.replace(
                "_",
                ""
            ),
        ]

        if any(
            variant
            and variant in q
            for variant in variants
        ):
            return column

    # -----------------------------------------------------
    # Find column containing mentioned values
    # -----------------------------------------------------

    if mentioned_values:

        for column in categorical_columns:

            values = (
                df[column]
                .dropna()
                .astype(str)
                .str.strip()
                .unique()
                .tolist()
            )

            normalized_values = {
                _normalize(value)
                for value in values
            }

            matches = 0

            for value in mentioned_values:

                if (
                    _normalize(value)
                    in normalized_values
                ):
                    matches += 1

            if matches >= 2:
                return column

    # -----------------------------------------------------
    # Common business dimensions
    # -----------------------------------------------------

    dimension_words = [
        "department",
        "dept",
        "region",
        "area",
        "location",
        "city",
        "state",
        "country",
        "category",
        "segment",
        "product",
        "team",
        "division",
        "gender",
        "customer",
        "employee",
        "name",
    ]

    for column in categorical_columns:

        column_text = (
            _normalize(column)
            .replace(
                "_",
                " "
            )
        )

        if any(
            word in column_text
            for word in dimension_words
        ):

            if any(
                word in q
                for word in dimension_words
            ):
                return column

    return None


# =========================================================
# FIND VALUES MENTIONED IN QUESTION
# =========================================================

def _mentioned_values(
    df,
    column,
    question
):

    question_text = _normalize(
        question
    )

    values = (
        df[column]
        .dropna()
        .astype(str)
        .str.strip()
        .unique()
        .tolist()
    )

    matches = []

    for value in values:

        value_text = _normalize(
            value
        )

        if not value_text:
            continue

        pattern = (
            r"(?<!\w)"
            + re.escape(value_text)
            + r"(?!\w)"
        )

        match = re.search(
            pattern,
            question_text
        )

        if match:

            matches.append(
                (
                    match.start(),
                    value
                )
            )

    matches.sort(
        key=lambda item: item[0]
    )

    result = []
    seen = set()

    for _, value in matches:

        key = _normalize(
            value
        )

        if key not in seen:

            seen.add(key)
            result.append(value)

    return result


# =========================================================
# SMART CHART TYPE
# =========================================================

def _choose_chart_type(
    question,
    dimension_col=None,
    metric_col=None,
    second_metric_col=None
):

    # -----------------------------------------------------
    # Numeric relationship
    #
    # Example:
    # Sales vs Profit
    # Salary against Experience
    # -----------------------------------------------------

    if (
        second_metric_col is not None
        and _relationship_requested(
            question
        )
    ):

        return "scatter"

    # -----------------------------------------------------
    # Time trend
    # -----------------------------------------------------

    if _trend_requested(
        question
    ):

        return "line"

    # -----------------------------------------------------
    # Percentage / share
    # -----------------------------------------------------

    if _share_requested(
        question
    ):

        return "pie"

    # -----------------------------------------------------
    # Comparisons
    #
    # North vs South remains BAR.
    # -----------------------------------------------------

    if _comparison_requested(
        question
    ):

        return "bar"

    # -----------------------------------------------------
    # Rankings
    # -----------------------------------------------------

    if (
        _highest_requested(question)
        or _lowest_requested(question)
    ):

        return "bar"

    # -----------------------------------------------------
    # Default
    # -----------------------------------------------------

    return "bar"


# =========================================================
# SMART CHART RENDERER
# =========================================================

def _render_chart(
    data,
    chart_type,
    dimension_col,
    metric_col,
    second_metric_col=None
):

    if (
        data is None
        or data.empty
    ):
        return False

    # =====================================================
    # BAR CHART
    # =====================================================

    if chart_type == "bar":

        chart_data = data.copy()

        if (
            dimension_col
            in chart_data.columns
        ):

            chart_data = (
                chart_data
                .set_index(
                    dimension_col
                )
            )

        if (
            metric_col
            not in chart_data.columns
        ):
            return False

        st.bar_chart(
            chart_data[
                metric_col
            ],
            use_container_width=True
        )

        return True

    # =====================================================
    # LINE CHART
    # =====================================================

    if chart_type == "line":

        chart_data = data.copy()

        if (
            dimension_col
            not in chart_data.columns
        ):
            return False

        chart_data[
            dimension_col
        ] = pd.to_datetime(
            chart_data[
                dimension_col
            ],
            errors="coerce"
        )

        chart_data = (
            chart_data
            .dropna(
                subset=[
                    dimension_col,
                    metric_col
                ]
            )
            .sort_values(
                dimension_col
            )
        )

        if chart_data.empty:
            return False

        chart_data = (
            chart_data
            .set_index(
                dimension_col
            )
        )

        st.line_chart(
            chart_data[
                metric_col
            ],
            use_container_width=True
        )

        return True

    # =====================================================
    # PIE CHART
    # =====================================================

    if chart_type == "pie":

        if (
            dimension_col
            not in data.columns
        ):
            return False

        pie_data = data[
            [
                dimension_col,
                metric_col
            ]
        ].copy()

        pie_data[
            metric_col
        ] = pd.to_numeric(
            pie_data[
                metric_col
            ],
            errors="coerce"
        )

        pie_data = (
            pie_data
            .dropna(
                subset=[
                    dimension_col,
                    metric_col
                ]
            )
        )

        if pie_data.empty:
            return False

        # Aggregate duplicate categories
        pie_data = (
            pie_data
            .groupby(
                dimension_col,
                as_index=False
            )[metric_col]
            .sum()
        )

        spec = {
            "mark": {
                "type": "arc",
                "tooltip": True
            },

            "encoding": {

                "theta": {
                    "field": metric_col,
                    "type": "quantitative"
                },

                "color": {
                    "field": dimension_col,
                    "type": "nominal"
                },

                "tooltip": [

                    {
                        "field": dimension_col,
                        "type": "nominal"
                    },

                    {
                        "field": metric_col,
                        "type": "quantitative"
                    }
                ]
            }
        }

        st.vega_lite_chart(
            pie_data,
            spec=spec,
            use_container_width=True
        )

        return True

    # =====================================================
    # SCATTER CHART
    # =====================================================

    if chart_type == "scatter":

        if (
            metric_col is None
            or second_metric_col is None
        ):
            return False

        scatter_data = data[
            [
                metric_col,
                second_metric_col
            ]
        ].copy()

        scatter_data[
            metric_col
        ] = pd.to_numeric(
            scatter_data[
                metric_col
            ],
            errors="coerce"
        )

        scatter_data[
            second_metric_col
        ] = pd.to_numeric(
            scatter_data[
                second_metric_col
            ],
            errors="coerce"
        )

        scatter_data = (
            scatter_data
            .dropna()
        )

        if scatter_data.empty:
            return False

        st.scatter_chart(
            scatter_data,
            x=metric_col,
            y=second_metric_col,
            use_container_width=True
        )

        return True

    return False


# =========================================================
# GENERIC GROUPED VISUALIZATION
# =========================================================

def _show_grouped(
    df,
    dimension_col,
    metric_col,
    aggregation,
    title,
    question
):

    data = df.copy()

    data[metric_col] = _numeric(
        data,
        metric_col
    )

    data = data.dropna(
        subset=[
            dimension_col,
            metric_col
        ]
    )

    if data.empty:
        return False

    # -----------------------------------------------------
    # Aggregation
    # -----------------------------------------------------

    if aggregation == "mean":

        grouped = (
            data
            .groupby(
                dimension_col
            )[metric_col]
            .mean()
        )

        label = "Average"

    elif aggregation == "count":

        grouped = (
            data
            .groupby(
                dimension_col
            )[metric_col]
            .count()
        )

        label = "Count"

    else:

        grouped = (
            data
            .groupby(
                dimension_col
            )[metric_col]
            .sum()
        )

        label = "Total"

    grouped = (
        grouped
        .sort_values(
            ascending=False
        )
        .head(20)
    )

    if grouped.empty:
        return False

    st.markdown(
        f"### 📊 {title}"
    )

    table = (
        grouped
        .rename(
            f"{label} {metric_col}"
        )
        .reset_index()
    )

    chart_metric = (
        f"{label} {metric_col}"
    )

    # -----------------------------------------------------
    # Smart chart selection
    # -----------------------------------------------------

    chart_type = _choose_chart_type(
        question,
        dimension_col,
        metric_col
    )

    # -----------------------------------------------------
    # Line chart needs a date dimension.
    #
    # If question asks for a trend but this dimension
    # isn't date-like, try to find a date column.
    # -----------------------------------------------------

    if chart_type == "line":

        dates = _date_columns(
            df
        )

        if dates:

            date_column = dates[0]

            trend_data = df.copy()

            trend_data[
                date_column
            ] = pd.to_datetime(
                trend_data[
                    date_column
                ],
                errors="coerce"
            )

            trend_data[
                metric_col
            ] = _numeric(
                trend_data,
                metric_col
            )

            trend_data = (
                trend_data
                .dropna(
                    subset=[
                        date_column,
                        metric_col
                    ]
                )
            )

            if not trend_data.empty:

                if aggregation == "mean":

                    trend_grouped = (
                        trend_data
                        .groupby(
                            date_column
                        )[metric_col]
                        .mean()
                        .reset_index()
                    )

                else:

                    trend_grouped = (
                        trend_data
                        .groupby(
                            date_column
                        )[metric_col]
                        .sum()
                        .reset_index()
                    )

                trend_grouped = (
                    trend_grouped
                    .sort_values(
                        date_column
                    )
                )

                _render_chart(
                    trend_grouped,
                    "line",
                    date_column,
                    metric_col
                )

            else:

                # Fallback
                _render_chart(
                    table,
                    "bar",
                    dimension_col,
                    chart_metric
                )

        else:

            # No date column available
            _render_chart(
                table,
                "bar",
                dimension_col,
                chart_metric
            )

    else:

        _render_chart(
            table,
            chart_type,
            dimension_col,
            chart_metric
        )

    # -----------------------------------------------------
    # Table
    # -----------------------------------------------------

    st.dataframe(
        table,
        use_container_width=True,
        hide_index=True
    )

    return True


# =========================================================
# GENERIC CATEGORY COMPARISON
# =========================================================

def _show_generic_comparison(
    df,
    question,
    dimension_col,
    metric_col
):

    values = _mentioned_values(
        df,
        dimension_col,
        question
    )

    # Need at least two categories
    if len(values) < 2:
        return False

    selected = values[:2]

    data = df.copy()

    data[metric_col] = _numeric(
        data,
        metric_col
    )

    data["__dimension__"] = (
        data[dimension_col]
        .astype(str)
        .str.strip()
    )

    data = data.dropna(
        subset=[
            metric_col
        ]
    )

    data = data[
        data[
            "__dimension__"
        ].isin(selected)
    ]

    if data.empty:
        return False

    q = _normalize(
        question
    )

    # -----------------------------------------------------
    # Aggregation
    # -----------------------------------------------------

    if (
        "average" in q
        or "avg" in q
        or "mean" in q
    ):

        grouped = (
            data
            .groupby(
                "__dimension__"
            )[metric_col]
            .mean()
        )

        aggregation_label = "Average"

    elif (
        "total" in q
        or "sum" in q
    ):

        grouped = (
            data
            .groupby(
                "__dimension__"
            )[metric_col]
            .sum()
        )

        aggregation_label = "Total"

    else:

        # Default comparison = TOTAL
        grouped = (
            data
            .groupby(
                "__dimension__"
            )[metric_col]
            .sum()
        )

        aggregation_label = "Total"

    grouped = grouped.reindex(
        selected
    )

    if grouped.isna().any():
        return False

    first_value = float(
        grouped.iloc[0]
    )

    second_value = float(
        grouped.iloc[1]
    )

    difference = abs(
        first_value
        - second_value
    )

    first_name = selected[0]
    second_name = selected[1]

    # -----------------------------------------------------
    # Heading
    # -----------------------------------------------------

    st.markdown(
        f"### 📊 {first_name} vs "
        f"{second_name} — "
        f"{aggregation_label} "
        f"{metric_col}"
    )

    # -----------------------------------------------------
    # Clean table
    # -----------------------------------------------------

    table = (
        grouped
        .rename(
            f"{aggregation_label} "
            f"{metric_col}"
        )
        .reset_index()
    )

    value_column = (
        f"{aggregation_label} "
        f"{metric_col}"
    )

    # IMPORTANT:
    # Replace internal __dimension__ name
    # with actual dataset column name.

    table.columns = [
        dimension_col,
        value_column
    ]

    # -----------------------------------------------------
    # Smart chart
    # -----------------------------------------------------

    chart_type = _choose_chart_type(
        question,
        dimension_col,
        metric_col
    )

    # Comparison remains BAR.
    _render_chart(
        table,
        chart_type,
        dimension_col,
        value_column
    )

    # -----------------------------------------------------
    # Table
    # -----------------------------------------------------

    st.dataframe(
        table,
        use_container_width=True,
        hide_index=True
    )

    # -----------------------------------------------------
    # Metrics
    # -----------------------------------------------------

    col1, col2 = st.columns(2)

    with col1:

        st.metric(
            "Difference",
            f"{difference:,.2f}"
        )

    with col2:

        if first_value > second_value:

            higher = first_name

        elif second_value > first_value:

            higher = second_name

        else:

            higher = "Equal"

        st.metric(
            "Higher",
            higher
        )

    # -----------------------------------------------------
    # Explanation
    # -----------------------------------------------------

    if first_value > second_value:

        st.info(
            f"{first_name} has higher "
            f"{aggregation_label.lower()} "
            f"{metric_col} than "
            f"{second_name}."
        )

    elif second_value > first_value:

        st.info(
            f"{second_name} has higher "
            f"{aggregation_label.lower()} "
            f"{metric_col} than "
            f"{first_name}."
        )

    else:

        st.info(
            f"{first_name} and "
            f"{second_name} have equal "
            f"{aggregation_label.lower()} "
            f"{metric_col}."
        )

    return True


# =========================================================
# PERSON RANKING
# =========================================================

def _show_top_employee(
    df,
    question,
    person_col,
    metric_col,
    descending=True
):

    if descending:

        ranking_requested = (
            _highest_requested(
                question
            )
        )

    else:

        ranking_requested = (
            _lowest_requested(
                question
            )
        )

    if not ranking_requested:
        return False

    data = df[
        [
            person_col,
            metric_col
        ]
    ].copy()

    data[metric_col] = _numeric(
        data,
        metric_col
    )

    data = data.dropna(
        subset=[
            person_col,
            metric_col
        ]
    )

    if data.empty:
        return False

    grouped = (
        data
        .groupby(
            person_col
        )[metric_col]
        .mean()
        .sort_values(
            ascending=not descending
        )
    )

    if grouped.empty:
        return False

    q = _normalize(
        question
    )

    limit_match = re.search(
        r"\btop\s+(\d+)\b",
        q
    )

    limit = (
        int(
            limit_match.group(1)
        )
        if limit_match
        else 1
    )

    result = grouped.head(
        limit
    )

    if descending:

        title = (
            f"Top {limit}"
            if limit > 1
            else "Highest"
        )

    else:

        title = "Lowest"

    st.markdown(
        f"### 📊 {title} "
        f"{metric_col}"
    )

    table = (
        result
        .rename(metric_col)
        .reset_index()
    )

    chart_type = _choose_chart_type(
        question,
        person_col,
        metric_col
    )

    _render_chart(
        table,
        chart_type,
        person_col,
        metric_col
    )

    st.dataframe(
        table,
        use_container_width=True,
        hide_index=True
    )

    return True


# =========================================================
# THRESHOLD ANALYSIS
# =========================================================

def _show_threshold(
    df,
    question,
    person_col,
    metric_col
):

    q = _normalize(
        question
    )

    patterns = [

        (
            r"(?:more than|greater than|above|over|exceeding)"
            r"\s*\$?\s*([\d,]+(?:\.\d+)?)",
            ">"
        ),

        (
            r"(?:less than|below|under)"
            r"\s*\$?\s*([\d,]+(?:\.\d+)?)",
            "<"
        ),

        (
            r"(?:at least|minimum of)"
            r"\s*\$?\s*([\d,]+(?:\.\d+)?)",
            ">="
        ),

        (
            r"(?:at most|maximum of)"
            r"\s*\$?\s*([\d,]+(?:\.\d+)?)",
            "<="
        ),
    ]

    operator = None
    threshold = None

    for pattern, op in patterns:

        match = re.search(
            pattern,
            q
        )

        if match:

            threshold = float(
                match
                .group(1)
                .replace(
                    ",",
                    ""
                )
            )

            operator = op

            break

    if operator is None:
        return False

    data = df[
        [
            person_col,
            metric_col
        ]
    ].copy()

    data[metric_col] = _numeric(
        data,
        metric_col
    )

    data = data.dropna(
        subset=[
            person_col,
            metric_col
        ]
    )

    if operator == ">":

        result = data[
            data[metric_col]
            > threshold
        ]

    elif operator == "<":

        result = data[
            data[metric_col]
            < threshold
        ]

    elif operator == ">=":

        result = data[
            data[metric_col]
            >= threshold
        ]

    else:

        result = data[
            data[metric_col]
            <= threshold
        ]

    result = result.sort_values(
        metric_col,
        ascending=False
    )

    st.markdown(
        f"### 📊 {metric_col} "
        f"{operator} "
        f"{threshold:,.0f}"
    )

    if result.empty:

        st.info(
            "No matching records were found."
        )

    else:

        st.dataframe(
            result,
            use_container_width=True,
            hide_index=True
        )

        chart_type = _choose_chart_type(
            question,
            person_col,
            metric_col
        )

        _render_chart(
            result,
            chart_type,
            person_col,
            metric_col
        )

    return True


