        errors="coerce"
    )

    data[second_metric_col] = pd.to_numeric(
        data[second_metric_col],
        errors="coerce"
    )

    data = data.dropna()

    if data.empty:
        return False

    st.markdown(
        f"### 🔵 {metric_col} vs "
        f"{second_metric_col}"
    )

    _render_chart(
        data,
        "scatter",
        metric_col,
        metric_col,
        second_metric_col
    )

    st.dataframe(
        data.head(20),
        use_container_width=True,
        hide_index=True
    )

    return True


# =========================================================
# GENERIC FALLBACK
# =========================================================

def _generic_visualization(
    df,
    question
):

    numeric_columns = (
        _numeric_columns(df)
    )

    categorical_columns = (
        _categorical_columns(df)
    )

    if (
        not numeric_columns
        or not categorical_columns
    ):
        return False

    metric = _find_metric_column(
        df,
        question
    )

    if metric is None:
        metric = numeric_columns[0]

    dimension = _find_dimension_column(
        df,
        question
    )

    if dimension is None:
        dimension = categorical_columns[0]

    if _average_requested(
        question
    ):

        return _show_grouped(
            df,
            dimension,
            metric,
            "mean",
            f"Average {metric} by "
            f"{dimension}",
            question
        )

    if _total_requested(
        question
    ):

        return _show_grouped(
            df,
            dimension,
            metric,
            "sum",
            f"Total {metric} by "
            f"{dimension}",
            question
        )

    return False


# =========================================================
# MAIN VISUALIZATION ENGINE
# =========================================================

def generate_visual_analysis(
    df,
    question=None
):
    """
    Generic question-specific visualization engine.

    Supported:

    - Category comparisons
    - Average comparisons
    - Total comparisons
    - Highest / lowest rankings
    - Threshold questions
    - Grouped averages
    - Grouped totals
    - Time trends
    - Pie charts for shares
    - Scatter charts for numeric relationships
    - Generic fallback visualizations

    Returns:

        True  -> visualization created
        False -> no suitable visualization
    """

    if (
        df is None
        or df.empty
        or not question
    ):
        return False

    data = _clean_columns(
        df
    )

    question = str(
        question
    ).strip()

    q = _normalize(
        question
    )

    numeric_columns = (
        _numeric_columns(
            data
        )
    )

    categorical_columns = (
        _categorical_columns(
            data
        )
    )

    if not numeric_columns:
        return False

    # =====================================================
    # FIND PRIMARY METRIC
    # =====================================================

    metric_col = _find_metric_column(
        data,
        question
    )

    # =====================================================
    # FIND SECOND METRIC
    # =====================================================

    second_metric_col = (
        _find_second_metric_column(
            data,
            question,
            metric_col
        )
    )

    # =====================================================
    # NUMERIC RELATIONSHIP
    # =====================================================

    if (
        _relationship_requested(
            question
        )
        and metric_col
        and second_metric_col
    ):

        if _show_scatter_relationship(
            data,
            question,
            metric_col,
            second_metric_col
        ):
            return True

    # =====================================================
    # FIND DIMENSION
    # =====================================================

    dimension_col = None

    if categorical_columns:

        # First look for two values mentioned
        # in the question.

        for column in categorical_columns:

            values = _mentioned_values(
                data,
                column,
                question
            )

            if len(values) >= 2:

                dimension_col = column

                break

        # Otherwise use normal dimension detection.

        if dimension_col is None:

            dimension_col = (
                _find_dimension_column(
                    data,
                    question
                )
            )

    # =====================================================
    # COMPARISON
    # =====================================================

    if (
        _comparison_requested(
            question
        )
        and dimension_col
    ):

        if metric_col is None:

            metric_col = (
                numeric_columns[0]
            )

        if _show_generic_comparison(
            data,
            question,
            dimension_col,
            metric_col
        ):

            return True

    # =====================================================
    # HIGHEST / LOWEST GROUP AVERAGE
    # =====================================================

    if (
        dimension_col
        and metric_col
        and _average_requested(
            question
        )
        and (
            _highest_requested(
                question
            )
            or _lowest_requested(
                question
            )
        )
    ):

        if _highest_requested(
            question
        ):

            if _show_highest_group_average(
                data,
                dimension_col,
                metric_col,
                question
            ):

                return True

    # =====================================================
    # TREND ANALYSIS
    # =====================================================

    if (
        _trend_requested(
            question
        )
        and metric_col
    ):

        dates = _date_columns(
            data
        )

        if dates:

            date_column = dates[0]

            trend_data = data.copy()

            trend_data[
                date_column
            ] = pd.to_datetime(
                trend_data[
                    date_column
                ],
                errors="coerce"
            )

            trend_data[
                metric_col
            ] = _numeric(
                trend_data,
                metric_col
            )

            trend_data = (
                trend_data
                .dropna(
                    subset=[
                        date_column,
                        metric_col
                    ]
                )
            )

            if not trend_data.empty:

                # Determine aggregation
                if _average_requested(
                    question
                ):

                    trend_grouped = (
                        trend_data
                        .groupby(
                            date_column
                        )[metric_col]
                        .mean()
                        .reset_index()
                    )

                else:

                    trend_grouped = (
                        trend_data
                        .groupby(
                            date_column
                        )[metric_col]
                        .sum()
                        .reset_index()
                    )

                trend_grouped = (
                    trend_grouped
                    .sort_values(
                        date_column
                    )
                )

                st.markdown(
                    f"### 📈 {metric_col} "
                    f"Trend Over Time"
                )

                _render_chart(
                    trend_grouped,
                    "line",
                    date_column,
                    metric_col
                )

                st.dataframe(
                    trend_grouped,
                    use_container_width=True,
                    hide_index=True
                )

                return True

    # =====================================================
    # PERSON COLUMN
    # =====================================================

    person_col = _find_column(
        data,
        [
            "Employee",
            "Employee_Name",
            "Employee Name",
            "Name",
            "Person",
            "Staff",
            "Customer",
        ]
    )

    if (
        person_col
        and metric_col
    ):

        # Threshold
        if _show_threshold(
            data,
            question,
            person_col,
            metric_col
        ):

            return True

        # Highest
        if _show_top_employee(
            data,
            question,
            person_col,
            metric_col,
            descending=True
        ):

            return True

        # Lowest
        if _show_top_employee(
            data,
            question,
            person_col,
            metric_col,
            descending=False
        ):

            return True

    # =====================================================
    # GROUPED AVERAGE
    # =====================================================

    if (
        dimension_col
        and metric_col
        and _average_requested(
            question
        )
    ):

        return _show_grouped(
            data,
            dimension_col,
            metric_col,
            "mean",
            f"Average {metric_col} by "
            f"{dimension_col}",
            question
        )

    # =====================================================
    # GROUPED TOTAL
    # =====================================================

    if (
        dimension_col
        and metric_col
        and _total_requested(
            question
        )
    ):

        return _show_grouped(
            data,
            dimension_col,
            metric_col,
            "sum",
            f"Total {metric_col} by "
            f"{dimension_col}",
            question
        )

    # =====================================================
    # PIE / SHARE ANALYSIS
    # =====================================================

    if (
        dimension_col
        and metric_col
        and _share_requested(
            question
        )
    ):

        data_copy = data.copy()

        data_copy[
            metric_col
        ] = _numeric(
            data_copy,
            metric_col
        )

        data_copy = (
            data_copy
            .dropna(
                subset=[
                    dimension_col,
                    metric_col
                ]
            )
        )

        grouped = (
            data_copy
            .groupby(
                dimension_col,
                as_index=False
            )[metric_col]
            .sum()
        )

        st.markdown(
            f"### 🥧 {metric_col} "
            f"Share by "
            f"{dimension_col}"
        )

        _render_chart(
            grouped,
            "pie",
            dimension_col,
            metric_col
        )

        st.dataframe(
            grouped,
            use_container_width=True,
            hide_index=True
        )

        return True

    # =====================================================
    # GENERIC FALLBACK
    # =====================================================

    if _generic_visualization(
        data,
        question
    ):

        return True

    # =====================================================
    # NOTHING FOUND
    # =====================================================

    return False
```

