        "Select metric",
        numeric_columns,
        key="outlier_metric"
    )

    outlier_series = safe_numeric_series(
        df,
        outlier_metric
    )

    if len(outlier_series) >= 4:

        q1 = outlier_series.quantile(0.25)
        q3 = outlier_series.quantile(0.75)

        iqr = q3 - q1

        lower_bound = q1 - 1.5 * iqr
        upper_bound = q3 + 1.5 * iqr

        outliers = outlier_series[
            (
                outlier_series < lower_bound
            )
            |
            (
                outlier_series > upper_bound
            )
        ]

        c1, c2, c3 = st.columns(3)

        with c1:

            st.metric(
                "Outliers",
                f"{len(outliers):,}"
            )

        with c2:

            st.metric(
                "Lower Bound",
                format_number(
                    lower_bound
                )
            )

        with c3:

            st.metric(
                "Upper Bound",
                format_number(
                    upper_bound
                )
            )

        if not outliers.empty:

            st.dataframe(
                outliers.to_frame(
                    name=outlier_metric
                ).head(20),
                use_container_width=True
            )

        else:

            st.success(
