    st.markdown(
        """
        **Ranking**
        - Which region has the highest sales?
        - Which region has the lowest sales?
        - What are the top 2 regions by sales?

        **Comparison**
        - Compare IT and Finance salaries.
        - Compare sales by region.

        **Aggregation**
        - What is the average salary?
        - What is the total sales?
        - Which department has the highest average salary?

        **Filtering**
        - Which employees earn more than 70000?
        - Which products have sales above 100000?

        **Individual lookup**
        - What is Asha's salary?
        - What is John's performance score?
        """
    )


# =========================================================
# QUESTION FORM
# =========================================================

with st.form(
    "question_form",
    clear_on_submit=False
):

    user_question = st.text_area(
        "Your question:",
        placeholder=(
            "Example:\n"
            "Which region has the highest sales?\n"
            "Which region has the lowest sales?\n"
            "What is the average salary?"
        ),
        height=160
    )

    ask_button = st.form_submit_button(
        "🚀 Ask"
    )


# =========================================================
# PROCESS QUESTIONS
# =========================================================

if (
    ask_button
    and
    user_question.strip()
):

    user_question = user_question.strip()

    questions = split_questions(
        user_question
    )

    if not questions:

        st.warning(
            "Please enter at least one question."
        )

        st.stop()


    # -----------------------------------------------------
    # Save current questions
    # -----------------------------------------------------

    st.session_state.last_questions = (
        questions
    )


    # =====================================================
    # VERIFIED CALCULATIONS
    # =====================================================

    verified_results = []

    with st.spinner(
        "🔎 Calculating verified answers..."
    ):

        for question in questions:

            try:

                verified_result = analyze_dataset(
                    df,
                    question
                )

            except Exception as e:

                verified_result = (
                    "Unable to calculate this question: "
                    f"{e}"
                )

            verified_results.append(
                {
                    "question": question,
                    "verified": verified_result
                }
            )


    st.session_state.last_verified_results = (
        verified_results
    )


    # =====================================================
    # SHOW VERIFICATION
    # =====================================================

    with st.expander(
        "🔍 Verified Calculations"
    ):

        for index, item in enumerate(
            verified_results,
            start=1
        ):

            st.markdown(
                f"### Question {index}"
            )

            st.write(
                item["question"]
            )

            st.code(
                str(
                    item["verified"]
                )
            )


    # =====================================================
    # BUILD VERIFIED CONTEXT
    # =====================================================

    verified_context_parts = []

    for index, item in enumerate(
        verified_results,
        start=1
    ):

        verified_context_parts.append(
            f"""
QUESTION {index}

USER QUESTION:
{item["question"]}

VERIFIED CALCULATION:
{item["verified"]}
"""
        )

    verified_context = "\n".join(
        verified_context_parts
    )


    # =====================================================
    # OLLAMA ANSWER PROMPT
    # =====================================================

    prompt = f"""
You are an AI Data Analyst.

Answer every question separately.

The calculations have already been performed and
verified by the application.

The VERIFIED CALCULATION is the absolute source
of truth.

IMPORTANT:

1. Answer EVERY question.
2. Never skip a question.
3. Never ask for another question.
4. Do not recalculate anything.
5. Do not change any number.
6. Do not invent any number.
7. Do not invent missing information.
8. Use only the verified calculation belonging
   to each question.
9. Do not mix answers between questions.
10. If the calculation gives a highest value,
    use that exact value.
11. If the calculation gives a lowest value,
    use that exact value.
12. If the calculation gives an average,
    describe it as an average.
13. If the calculation gives a total,
    describe it as a total.
14. If the calculation gives a list,
    preserve the list.
15. Keep each answer concise.
16. Do not mention Python.
17. Do not mention Ollama.
18. Do not mention the analysis engine.
19. Do not mention prompts.
20. Do not say information is missing if it
    exists in the verified calculation.

VERIFIED CALCULATIONS:

{verified_context}

FORMAT:

Question 1:
<direct answer>

Question 2:
<direct answer>

Question 3:
<direct answer>

Continue until every question is answered.

Return ONLY the answers.
"""


    # =====================================================
    # GET AI ANSWER
    # =====================================================

    with st.spinner(
        "🤖 Preparing AI answers..."
    ):

        answer, error = call_ollama(
            prompt
        )


    if error:

        st.error(
            error
        )

        # -------------------------------------------------
        # Fallback: show verified calculations directly
        # -------------------------------------------------

        st.warning(
            "Showing the verified calculations directly "
            "because the AI explanation could not be generated."
        )

        answer = "\n\n".join(
            [
                (
                    f"**Question {i}:**\n"
                    f"{item['verified']}"
                )
                for i, item in enumerate(
                    verified_results,
                    start=1
                )
            ]
        )

    else:

        st.subheader(
            "🤖 AI Answer"
        )

        st.markdown(
            answer
        )


    # =====================================================
    # SAVE HISTORY
    # =====================================================

    st.session_state.chat_history.append(
        {
            "question": user_question,
            "answer": answer
        }
    )


    # =====================================================
    # QUESTION-SPECIFIC VISUALIZATIONS
    # =====================================================

    st.divider()

    st.header(
        "📊 Automatic Visualization"
    )

    visualization_created = False


    for index, question in enumerate(
        questions,
        start=1
    ):

        st.subheader(
            f"Question {index}"
        )

        st.caption(
            question
        )

        current_visualization = False


        # -------------------------------------------------
        # First try the new built-in visual logic
        # -------------------------------------------------

        try:

            current_visualization = (
                create_question_visualization(
                    df,
                    question
                )
            )

        except Exception:

            current_visualization = False


        # -------------------------------------------------
        # Fallback to existing visual engine
        # -------------------------------------------------

        if not current_visualization:

            try:

                current_visualization = (
                    generate_visual_analysis(
                        df,
                        question
                    )
                )

            except Exception:

                current_visualization = False


        if current_visualization:

            visualization_created = True

        else:

            st.info(
                "No automatic visualization is available "
                "for this question."
            )


    if not visualization_created:

        st.caption(
            "The visualization engine did not find a suitable "
            "chart for the submitted question."
        )


# =========================================================
# ANALYSIS HISTORY
# =========================================================

if st.session_state.chat_history:

    st.divider()

    st.header(
        "🧠 Analysis History"
    )

    for index, chat in enumerate(
        reversed(
            st.session_state.chat_history
        ),
        start=1
    ):

        with st.expander(
            f"Analysis {index}: "
            f"{chat['question'][:80]}"
        ):

            st.markdown(
                f"**You:** {chat['question']}"
            )

            st.markdown(
                "**🤖 AI:**"
            )

            st.markdown(
                chat["answer"]
            )


# =========================================================
# FOOTER
# =========================================================

st.divider()

st.caption(
    "📊 AI Data Analyst • "
    "Verified calculations + AI explanations + "
    "automatic business visualization"
)

import re
import pandas as pd
import streamlit as st


def _normalize(value):
    return re.sub(r"\s+", " ", str(value).strip().lower())


def _find_column(df, candidates):
    normalized = {_normalize(c).replace(" ", ""): c for c in df.columns}

    # Exact normalized match first.
    for candidate in candidates:
        key = _normalize(candidate).replace(" ", "")
        if key in normalized:
            return normalized[key]

    # Then partial match.
    for column in df.columns:
        key = _normalize(column).replace(" ", "")
        for candidate in candidates:
            candidate_key = _normalize(candidate).replace(" ", "")
            if candidate_key and candidate_key in key:
                return column

    return None


def _numeric(df, column):
    return pd.to_numeric(df[column], errors="coerce")


def _mentioned_values(df, column, question):
    """Return dataset values explicitly mentioned in the question, in question order."""
    question_text = _normalize(question)
    values = [
        value
        for value in df[column].dropna().astype(str).str.strip().unique().tolist()
        if value
    ]

    matches = []
    for value in values:
        value_text = _normalize(value)
        if not value_text:
            continue
        pattern = r"(?<!\w)" + re.escape(value_text) + r"(?!\w)"
        match = re.search(pattern, question_text)
        if match:
            matches.append((match.start(), value))

    matches.sort(key=lambda item: item[0])

    result = []
    seen = set()
    for _, value in matches:
        key = _normalize(value)
        if key not in seen:
            seen.add(key)
            result.append(value)

    return result


def _comparison_requested(question):
    q = _normalize(question)
    return any(
        phrase in q
        for phrase in (
            "compare",
            "comparison",
            "versus",
            " vs ",
            "difference between",
            "compare between",
        )
    )


def _show_comparison(df, question, department_col, metric_col, metric_label):
    departments = _mentioned_values(df, department_col, question)

    if len(departments) < 2:
        return False

    selected = departments[:2]
    working = df.copy()
    working[metric_col] = _numeric(working, metric_col)
    working["__dimension__"] = working[department_col].astype(str).str.strip()

    grouped = (
        working[working["__dimension__"].isin(selected)]
        .dropna(subset=[metric_col])
        .groupby("__dimension__")[metric_col]
        .mean()
        .reindex(selected)
    )

    if grouped.isna().any() or len(grouped) != 2:
        return False

    first, second = selected
    first_value = float(grouped.loc[first])
    second_value = float(grouped.loc[second])
    difference = abs(first_value - second_value)

    st.markdown(f"### 📊 {first} vs {second} — Average {metric_label}")
    st.bar_chart(grouped.rename(f"Average {metric_label}"), use_container_width=True)

    table = grouped.rename(f"Average {metric_label}").reset_index()
    table.columns = [department_col, f"Average {metric_label}"]
    st.dataframe(table, use_container_width=True, hide_index=True)

    col1, col2 = st.columns(2)
    with col1:
        st.metric(f"{metric_label} Difference", f"{difference:,.0f}")
    with col2:
        if first_value > second_value:
            higher = first
        elif second_value > first_value:
            higher = second
        else:
            higher = "Equal"
        st.metric(f"Higher Average {metric_label}", higher)

    return True


def _show_top_employee(df, question, person_col, metric_col, metric_label, descending=True):
    q = _normalize(question)
    ranking_words = ("highest", "top", "most", "maximum", "max", "best") if descending else (
        "lowest", "least", "minimum", "min", "worst", "smallest"
    )
    if not any(word in q for word in ranking_words):
        return False

    data = df[[person_col, metric_col]].copy()
    data[metric_col] = _numeric(data, metric_col)
    data = data.dropna(subset=[person_col, metric_col])
    if data.empty:
        return False

    grouped = (
        data.groupby(person_col)[metric_col]
        .mean()
        .sort_values(ascending=not descending)
    )
    if grouped.empty:
        return False

    limit_match = re.search(r"\btop\s+(\d+)\b", q)
    limit = int(limit_match.group(1)) if limit_match else 1
    result = grouped.head(limit)

    title = f"Top {limit}" if descending and limit > 1 else (
        "Highest" if descending else "Lowest"
    )
    st.markdown(f"### 📊 {title} {metric_label}")
    st.bar_chart(result.rename(metric_label), use_container_width=True)

    table = result.rename(metric_label).reset_index()
    st.dataframe(table, use_container_width=True, hide_index=True)
    return True


def _show_threshold(df, question, person_col, metric_col, metric_label):
    q = _normalize(question)
    patterns = [
        (r"(?:more than|greater than|above|over|exceeding)\s*\$?\s*([\d,]+(?:\.\d+)?)", ">"),
        (r"(?:less than|below|under)\s*\$?\s*([\d,]+(?:\.\d+)?)", "<"),
        (r"(?:at least|minimum of)\s*\$?\s*([\d,]+(?:\.\d+)?)", ">="),
        (r"(?:at most|maximum of)\s*\$?\s*([\d,]+(?:\.\d+)?)", "<="),
    ]

    operator = threshold = None
    for pattern, op in patterns:
        match = re.search(pattern, q)
        if match:
            threshold = float(match.group(1).replace(",", ""))
            operator = op
            break

    if operator is None:
        return False

    data = df[[person_col, metric_col]].copy()
    data[metric_col] = _numeric(data, metric_col)
    data = data.dropna(subset=[person_col, metric_col])

    if operator == ">":
        result = data[data[metric_col] > threshold]
    elif operator == "<":
        result = data[data[metric_col] < threshold]
    elif operator == ">=":
        result = data[data[metric_col] >= threshold]
    else:
        result = data[data[metric_col] <= threshold]

    result = result.sort_values(metric_col, ascending=False)
    st.markdown(f"### 📊 Employees {operator} {threshold:,.0f} {metric_label}")
    if result.empty:
        st.info("No matching employees were found.")
    else:
        st.dataframe(result, use_container_width=True, hide_index=True)
        st.bar_chart(result.set_index(person_col)[metric_col], use_container_width=True)
    return True


def _show_grouped(df, dimension_col, metric_col, aggregation, title):
    data = df.copy()
    data[metric_col] = _numeric(data, metric_col)
    data = data.dropna(subset=[dimension_col, metric_col])
    if data.empty:
        return False

    if aggregation == "mean":
        grouped = data.groupby(dimension_col)[metric_col].mean()
        label = "Average"
    else:
        grouped = data.groupby(dimension_col)[metric_col].sum()
        label = "Total"

    grouped = grouped.sort_values(ascending=False).head(20)
    if grouped.empty:
        return False

    st.markdown(f"### 📊 {title}")
    st.bar_chart(grouped.rename(f"{label} {metric_col}"), use_container_width=True)
    table = grouped.rename("Value").reset_index()
    st.dataframe(table, use_container_width=True, hide_index=True)
    return True


def generate_visual_analysis(df, question=None):
    """Generate one question-specific visualization and return True when successful."""
    if df is None or df.empty or not question:
        return False

    data = df.copy()
    data.columns = [str(column).strip() for column in data.columns]
    q = _normalize(question)

    department_col = _find_column(data, ["Department", "Dept", "Team", "Division"])
    person_col = _find_column(data, ["Employee", "Employee_Name", "Employee Name", "Name", "Person", "Staff"])
    salary_col = _find_column(data, ["Salary", "Salaries", "Pay", "Wage", "Compensation", "Income"])
    performance_col = _find_column(data, ["Performance_Score", "Performance Score", "Performance", "Score", "Rating"])
    experience_col = _find_column(data, ["Experience", "Years_Experience", "Years Experience", "Years", "Tenure"])

    # Comparison is deliberately handled first so it cannot fall through to a
    # generic salary visualization.
    if _comparison_requested(question) and department_col:
        if salary_col and any(word in q for word in ("salary", "salaries", "paid", "pay", "earn", "income")):
            if _show_comparison(data, question, department_col, salary_col, "Salary"):
                return True
        if performance_col and any(word in q for word in ("performance", "performing", "score", "scores", "rating", "ratings")):
            if _show_comparison(data, question, department_col, performance_col, "Performance"):
                return True
        if experience_col and any(word in q for word in ("experience", "experienced", "years", "tenure")):
            if _show_comparison(data, question, department_col, experience_col, "Experience"):
                return True

    # Person-specific / ranking visualizations.
    if person_col and salary_col and any(word in q for word in ("salary", "salaries", "paid", "pay", "earn", "income")):
        if _show_threshold(data, question, person_col, salary_col, "salary"):
            return True
        if _show_top_employee(data, question, person_col, salary_col, "Salary", descending=True):
            return True
        if _show_top_employee(data, question, person_col, salary_col, "Salary", descending=False):
            return True

    if person_col and performance_col and any(word in q for word in ("performance", "performing", "score", "scores", "rating", "ratings")):
        if _show_top_employee(data, question, person_col, performance_col, "Performance", descending=True):
            return True
        if _show_top_employee(data, question, person_col, performance_col, "Performance", descending=False):
            return True

    if person_col and experience_col and any(word in q for word in ("experience", "experienced", "years", "tenure")):
        if _show_top_employee(data, question, person_col, experience_col, "Experience", descending=True):
            return True
        if _show_top_employee(data, question, person_col, experience_col, "Experience", descending=False):
            return True

    # Department salary questions.
    if department_col and salary_col and "salary" in q:
        if "average" in q or "mean" in q or "avg" in q:
            return _show_grouped(
                data,
                department_col,
                salary_col,
                "mean",
                "Average Salary by Department",
            )
        if "total" in q or "sum" in q:
            return _show_grouped(
                data,
                department_col,
                salary_col,
                "sum",
                "Total Salary by Department",
            )

    # Generic category-vs-numeric fallback for other datasets.
    numeric_columns = data.select_dtypes(include="number").columns.tolist()
    categorical_columns = data.select_dtypes(include=["object", "category"]).columns.tolist()
    if categorical_columns and numeric_columns:
        dimension = categorical_columns[0]
        metric = numeric_columns[0]
        if any(word in q for word in ("average", "mean", "avg")):
            return _show_grouped(data, dimension, metric, "mean", f"Average {metric} by {dimension}")
        if any(word in q for word in ("total", "sum")):
            return _show_grouped(data, dimension, metric, "sum", f"Total {metric} by {dimension}")

    return False
